#[test]
fn r_fixtures_survfit_km() {
    let doc = load_topic("survfit_km");
    let mut report = Report::new("survfit_km");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"];
        let prepared = (|| -> Result<SurvfitKMResult, String> {
            let KMCase { data, options } = km_case(&doc, case)?;
            let fit = survfitkm(&data, &options).map_err(|err| format!("survfitkm: {err}"))?;
            let curves = expected["fit"]["curves"].as_array().ok_or("no curves")?;
            if curves.len() != fit.n_curves() {
                return Err(format!(
                    "{} R curves but {} fitted",
                    curves.len(),
                    fit.n_curves()
                ));
            }
            Ok(fit)
        })();
        match prepared {
            Err(message) => {
                for aspect in KM_ASPECTS {
                    if *aspect == "summary_times" && expected["summary_times"].is_null() {
                        continue;
                    }
                    if *aspect == "quantile" && expected["quantile"].is_null() {
                        continue;
                    }
                    report.record(name, aspect, Err(message.clone()));
                }
            }
            Ok(fit) => {
                let curves = expected["fit"]["curves"].as_array().expect("checked");
                for aspect in KM_ASPECTS {
                    let result = match *aspect {
                        "fit" => check_km_fit(&fit, &expected["fit"]),
                        "summary_table" => check_km_summary_table(
                            &fit,
                            &expected["summary_table"],
                            km_summary_rmean(name),
                        ),
                        "summary_std_err" => {
                            let summary = summary_survfit(&fit, false);
                            assert_optional(
                                summary.std_err.as_deref(),
                                &expected["summary_std_err"],
                                RTOL_VAR,
                                "summary.std_err",
                            )
                        }
                        "summary_times" => {
                            if expected["summary_times"].is_null() {
                                continue;
                            }
                            check_km_summary_times(&fit, &expected["summary_times"])
                        }
                        "quantile" => {
                            if expected["quantile"].is_null() {
                                continue;
                            }
                            check_km_quantile(&fit, &expected["quantile"])
                        }
                        _ => fit.curve_ranges().into_iter().zip(curves).try_for_each(
                            |(range, curve)| check_km_curve(&fit, range, curve, aspect),
                        ),
                    };
                    report.record(name, aspect, result);
                }
            }
        }
    }
    report.finish();
}

// --- survdiff ---------------------------------------------------------------

#[test]
fn r_fixtures_survdiff() {
    let doc = load_topic("survdiff");
    let mut report = Report::new("survdiff");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let result = (|| -> Result<SurvDiffResult, String> {
            let frame = case_frame(&doc, case)?;
            let formula = text(&case["formula"]).ok_or("no formula")?;
            let response = response(formula, &frame)?;
            let rho = case["args"]["rho"].as_f64().unwrap_or(0.0);
            let mut group_term = None;
            let mut strata_term = None;
            let mut offset_term = None;
            for term in rhs_terms(formula) {
                if let Some(inner) = term
                    .strip_prefix("strata(")
                    .and_then(|t| t.strip_suffix(')'))
                {
                    strata_term = Some(inner.to_string());
                } else if let Some(inner) = term
                    .strip_prefix("offset(")
                    .and_then(|t| t.strip_suffix(')'))
                {
                    offset_term = Some(inner.to_string());
                } else if group_term.replace(term).is_some() {
                    return unsupported("harness: several grouping terms");
                }
            }
            if let Some(offset) = offset_term {
                // one-sample test against expected survival, given in args
                let expected = arg_nums(case, &offset).ok_or("offset values not in args")?;
                let rows: Vec<usize> = (0..response.time.len())
                    .filter(|&i| response.time[i].is_finite() && expected[i].is_finite())
                    .collect();
                return survdiff_one_sample(
                    &pick(&response.status, &rows),
                    &pick(&expected, &rows),
                    rho,
                )
                .map_err(|err| format!("survdiff_one_sample: {err}"));
            }
            let group_column = frame.get(&group_term.ok_or("no group term")?)?;
            let group_levels = group_column.levels();
            let group_all: Vec<i32> = (0..frame.nrow())
                .map(|i| {
                    group_levels
                        .iter()
                        .position(|l| Some(l.as_str()) == group_column.label(i).as_deref())
                        .map_or(-1, |p| p as i32)
                })
                .collect();
            let strata_all: Option<Vec<i32>> = match &strata_term {
                Some(term) => {
                    let column = frame.get(term)?;
                    let levels = column.levels();
                    Some(
                        (0..frame.nrow())
                            .map(|i| {
                                levels
                                    .iter()
                                    .position(|l| Some(l.as_str()) == column.label(i).as_deref())
                                    .map_or(-1, |p| p as i32)
                            })
                            .collect(),
                    )
                }
                None => None,
            };
            let rows: Vec<usize> = (0..frame.nrow())
                .filter(|&i| {
                    response.time[i].is_finite()
                        && group_all[i] >= 0
                        && strata_all.as_ref().is_none_or(|s| s[i] >= 0)
                })
                .collect();
            let data = SurvdiffData::try_new(
                response.start.as_ref().map(|s| pick(s, &rows)),
                pick(&response.time, &rows),
                pick(&response.status, &rows),
                pick(&group_all, &rows),
                strata_all.as_ref().map(|s| pick(s, &rows)),
            )
            .map_err(|err| format!("data: {err}"))?;
            survdiff(&data, rho, true).map_err(|err| format!("survdiff: {err}"))
        })();
        let expected = &case["expected"];
        match result {
            Err(message) => {
                for aspect in ["counts", "var", "chisq"] {
                    report.record(name, aspect, Err(message.clone()));
                }
            }
            Ok(fit) => {
                let as_matrix = |value: &Value| -> Result<Vec<Vec<f64>>, String> {
                    if value
                        .as_array()
                        .is_some_and(|v| v.first().is_some_and(Value::is_array))
                    {
                        matrix(value)
                    } else {
                        Ok(nums(value)?.into_iter().map(|v| vec![v]).collect())
                    }
                };
                let counts = (|| {
                    let n: Vec<f64> = fit.n.iter().map(|&v| v as f64).collect();
                    assert_vec(&n, &nums(&expected["n"])?, 0.0, "n")?;
                    assert_matrix(&fit.obs, &as_matrix(&expected["obs"])?, 1e-12, "obs")?;
                    assert_matrix(&fit.exp, &as_matrix(&expected["exp"])?, RTOL_COEF, "exp")
                })();
                report.record(name, "counts", counts);
                let var =
                    (|| assert_matrix(&fit.var, &as_matrix(&expected["var"])?, RTOL_VAR, "var"))();
                report.record(name, "var", var);
                let chisq = (|| {
                    assert_scalar(fit.chisq, num(&expected["chisq"])?, RTOL_VAR, "chisq")?;
                    assert_scalar(fit.df as f64, num(&expected["df"])?, 0.0, "df")?;
                    // p-values are compared with an absolute floor, they underflow
                    assert_vec_within(
                        &[fit.pvalue],
                        &[num(&expected["pvalue"])?],
                        RTOL_VAR,
                        1e-300,
                        "pvalue",
                    )
                })();
                report.record(name, "chisq", chisq);
            }
        }
    }
    report.finish();
}

// --- survfit_multistate -----------------------------------------------------

/// A multi-state `Surv(time, event)` / `Surv(start, stop, event)` response:
/// event is a factor whose first level is the censoring code.
struct MstateResponse {
    start: Option<Vec<f64>>,
    time: Vec<f64>,
    state: Vec<i32>,
    states: Vec<String>,
}

fn mstate_response(formula: &str, frame: &Frame) -> Result<MstateResponse, String> {
    let lhs = formula.split('~').next().ok_or("formula without ~")?.trim();
    let inner = lhs
        .strip_prefix("Surv(")
        .and_then(|rest| rest.strip_suffix(')'))
        .ok_or_else(|| format!("unsupported: harness: response {lhs:?}"))?;
    let args: Vec<&str> = inner.split(',').map(str::trim).collect();
    let status_name = *args.last().ok_or("empty Surv()")?;
    let column = frame.get(status_name)?;
    let levels = match column {
        Column::Str(_, levels) if !levels.is_empty() => levels.clone(),
        _ => return unsupported("harness: multi-state status must be a factor"),
    };
    let state = (0..column.len())
        .map(|i| {
            column
                .label(i)
                .and_then(|label| levels.iter().position(|l| *l == label))
                .map_or(-1, |p| p as i32)
        })
        .collect();
    let (start, time) = match args.len() {
        2 => (None, frame.get(args[0])?.numeric(args[0])?),
        3 => (
            Some(frame.get(args[0])?.numeric(args[0])?),
            frame.get(args[1])?.numeric(args[1])?,
        ),
        _ => return unsupported(format!("harness: Surv() with {} arguments", args.len())),
    };
    Ok(MstateResponse {
        start,
        time,
        state,
        states: levels[1..].to_vec(),
    })
}

fn aj_case(doc: &Value, case: &Value) -> Result<(SurvfitAJData, SurvfitAJOptions), String> {
    let frame = case_frame(doc, case)?;
    let formula = text(&case["formula"]).ok_or("no formula")?;
    let args = &case["args"];
    let response = mstate_response(formula, &frame)?;
    let (strata, _) = strata_codes(formula, &frame)?;
    let id = match text(&args["id"]) {
        Some(column) => Some(integer_labels(frame.get(column)?, column)?),
        None => None,
    };
    let (istate, istate_levels) = match text(&args["istate"]) {
        Some(column) => {
            let values = frame.get(column)?;
            let levels = values.levels();
            let labels: Vec<Option<String>> = (0..values.len()).map(|i| values.label(i)).collect();
            (Some(labels), Some(levels))
        }
        None => (None, None),
    };
    let rows: Vec<usize> = (0..frame.nrow())
        .filter(|&i| {
            response.time[i].is_finite()
                && response.start.as_ref().is_none_or(|s| s[i].is_finite())
                && response.state[i] >= 0
                && strata.as_ref().is_none_or(|s| s[i] >= 0)
                && id.as_ref().is_none_or(|v| v[i] != i64::MIN)
                && istate.as_ref().is_none_or(|v| v[i].is_some())
        })
        .collect();
    let data = SurvfitAJData::try_new(
        response.start.as_ref().map(|s| pick(s, &rows)),
        pick(&response.time, &rows),
        pick(&response.state, &rows),
        response.states.clone(),
        arg_nums(case, "weights").map(|w| pick(&w, &rows)),
        strata.as_ref().map(|s| pick(s, &rows)),
        id.as_ref().map(|v| pick(v, &rows)),
        istate.map(|v| {
            rows.iter()
                .map(|&i| v[i].clone().expect("complete"))
                .collect()
        }),
        istate_levels,
        None,
    )
    .map_err(|err| format!("data: {err}"))?;
    let options = SurvfitAJOptions {
        se_fit: !matches!(args["se.fit"].as_bool(), Some(false)),
        conf_int: args["conf.int"].as_f64().unwrap_or(0.95),
        conf_type: ConfType::parse(text(&args["conf.type"]).unwrap_or("log"))
            .map_err(|err| err.to_string())?,
        influence: !case["expected"]["influence_pstate"].is_null(),
        start_time: args["start.time"].as_f64(),
        p0: arg_nums(case, "p0"),
        entry: false,
        time0: matches!(args["time0"].as_bool(), Some(true)),
        timefix: !matches!(args["timefix"].as_bool(), Some(false)),
    };
    Ok((data, options))
}

fn check_aj_curve(
    fit: &SurvfitAJResult,
    range: std::ops::Range<usize>,
    curve: &Value,
    aspect: &str,
) -> Result<(), String> {
    let path = format!("curve[{}]", text(&curve["name"]).unwrap_or("?"));
    let slice = |values: &[Vec<f64>]| values[range.clone()].to_vec();
    let optional = |values: &Option<Vec<Vec<f64>>>, key: &str| -> Result<(), String> {
        match (values, curve[key].is_null()) {
            (None, true) => Ok(()),
            (Some(values), false) => assert_matrix(
                &slice(values),
                &matrix(&curve[key])?,
                RTOL_VAR,
                &format!("{path}.{key}"),
            ),
            (Some(_), true) => Err(format!("{path}.{key}: reported but absent in R")),
            (None, false) => Err(format!("{path}.{key}: missing")),
        }
    };
    match aspect {
        "time_counts" => {
            assert_vec(
                &fit.time[range.clone()],
                &nums(&curve["time"])?,
                0.0,
                &format!("{path}.time"),
            )?;
            assert_matrix(
                &slice(&fit.n_risk),
                &matrix(&curve["n_risk"])?,
                0.0,
                &format!("{path}.n_risk"),
            )?;
            assert_matrix(
                &slice(&fit.n_event),
                &matrix(&curve["n_event"])?,
                0.0,
                &format!("{path}.n_event"),
            )?;
            assert_matrix(
                &slice(&fit.n_censor),
                &matrix(&curve["n_censor"])?,
                0.0,
                &format!("{path}.n_censor"),
            )?;
            assert_matrix(
                &slice(&fit.n_transition),
                &matrix(&curve["n_transition"])?,
                0.0,
                &format!("{path}.n_transition"),
            )
        }
        "pstate" => assert_matrix(
            &slice(&fit.pstate),
            &matrix(&curve["pstate"])?,
            RTOL_COEF,
            &format!("{path}.pstate"),
        ),
        "cumhaz" => assert_matrix(
            &slice(&fit.cumhaz),
            &matrix(&curve["cumhaz"])?,
            RTOL_COEF,
            &format!("{path}.cumhaz"),
        ),
        "std_err" => optional(&fit.std_err, "std_err"),
        "std_chaz" => optional(&fit.std_chaz, "std_chaz"),
        "conf" => {
            optional(&fit.lower, "lower")?;
            optional(&fit.upper, "upper")
        }
        other => unsupported(format!("aspect {other}")),
    }
}

fn check_aj_fit(fit: &SurvfitAJResult, expected: &Value) -> Result<(), String> {
    let n: Vec<f64> = fit.n.iter().map(|&v| v as f64).collect();
    assert_vec(&n, &nums(&expected["n"])?, 0.0, "n")?;
    let states: Vec<&str> = names_of(&expected["states"]);
    if fit.states != states {
        return Err(format!("states: {:?} != {states:?}", fit.states));
    }
    let p0 = if expected["p0"]
        .as_array()
        .is_some_and(|v| v.first().is_some_and(Value::is_array))
    {
        matrix(&expected["p0"])?
    } else {
        vec![nums(&expected["p0"])?]
    };
    assert_matrix(&fit.p0, &p0, RTOL_COEF, "p0")?;
    assert_scalar(fit.t0, num(&expected["t0"])?, 0.0, "t0")?;
    let actual_strata: Vec<f64> = fit
        .strata
        .as_ref()
        .map(|s| s.iter().map(|&v| v as f64).collect())
        .unwrap_or_default();
    assert_vec(&actual_strata, &expected_strata(expected), 0.0, "strata")?;
    // transitions: R drops the states that never occur and the empty columns
    let table = &expected["transitions"];
    let rownames = names_of(&table["rownames"]);
    let colnames = names_of(&table["colnames"]);
    let values = matrix(&table["values"])?;
    for (r, from) in rownames.iter().enumerate() {
        let from_index = fit
            .states
            .iter()
            .position(|s| s == from)
            .ok_or("unknown from state")?;
        for (c, to) in colnames.iter().enumerate() {
            let to_index = if *to == "(censored)" {
                fit.states.len()
            } else {
                fit.states
                    .iter()
                    .position(|s| s == to)
                    .ok_or("unknown to state")?
            };
            assert_scalar(
                fit.transitions[from_index][to_index],
                values[r][c],
                0.0,
                &format!("transitions[{from},{to}]"),
            )?;
        }
    }
    Ok(())
}

/// `fit$influence.pstate` as `[state][subject][time]` layers.
fn check_aj_influence(fit: &SurvfitAJResult, expected: &Value) -> Result<(), String> {
    let influence = fit
        .influence_pstate
        .as_ref()
        .and_then(|list| list.first())
        .ok_or("no influence")?;
    let layers = expected.as_array().ok_or("influence is not an array")?;
    for (state, layer) in layers.iter().enumerate() {
        let expected_layer = matrix(layer)?;
        let actual: Vec<Vec<f64>> = influence
            .values
            .iter()
            .map(|by_time| by_time.iter().map(|row| row[state]).collect())
            .collect();
        assert_matrix(
            &actual,
            &expected_layer,
            RTOL_VAR,
            &format!("influence[state {state}]"),
        )?;
    }
    Ok(())
}

