// km: aggregate_survfit (population averages of survfit(coxfit, newdata))
// ---------------------------------------------------------------------------

/// R's `as.factor` of a numeric fixture vector: codes into the sorted
/// distinct values, labelled the way `as.character` prints them.
fn numeric_factor(values: &[f64], name: Option<String>) -> Result<GroupingFactor, String> {
    let mut levels: Vec<f64> = values.to_vec();
    levels.sort_by(f64::total_cmp);
    levels.dedup();
    let codes = values
        .iter()
        .map(|value| {
            levels
                .binary_search_by(|level| level.total_cmp(value))
                .map_err(|_| format!("by value {value} is not one of its own levels"))
        })
        .collect::<Result<Vec<_>, _>>()?;
    let labels = levels.iter().map(|&level| r_number_label(level)).collect();
    GroupingFactor::try_new(codes, labels, name).map_err(|err| err.to_string())
}

fn r_number_label(value: f64) -> String {
    if value.fract() == 0.0 && value.abs() < 1e15 {
        format!("{}", value as i64)
    } else {
        format!("{value}")
    }
}

/// The `by` argument of a case: a JSON array of vectors (unnamed list) or
/// an object whose order is `by_names` (named list).
fn aggregate_by(args: &Value) -> Result<Vec<GroupingFactor>, String> {
    match &args["by"] {
        Value::Null => Ok(Vec::new()),
        Value::Array(vectors) => vectors
            .iter()
            .map(|vector| numeric_factor(&nums(vector)?, None))
            .collect(),
        Value::Object(map) => names_of(&args["by_names"])
            .into_iter()
            .map(|name| {
                let vector = map.get(name).ok_or_else(|| format!("by has no {name}"))?;
                numeric_factor(&nums(vector)?, Some(name.to_string()))
            })
            .collect(),
        other => Err(format!("unexpected by: {other}")),
    }
}

/// `pstate` as the generator stores it: one time x data matrix per state.
fn aggregate_pstate(value: &Value) -> Result<Array3<f64>, String> {
    let states = value.as_array().ok_or("pstate is not a list of matrices")?;
    let matrices = states.iter().map(matrix).collect::<Result<Vec<_>, _>>()?;
    let n_state = matrices.len();
    let n_time = matrices.first().map_or(0, Vec::len);
    let n_data = matrices
        .first()
        .and_then(|rows| rows.first())
        .map_or(0, Vec::len);
    let mut pstate = Array3::zeros((n_time, n_data, n_state));
    for (s, rows) in matrices.iter().enumerate() {
        if rows.len() != n_time {
            return Err(format!("pstate state {s} has {} rows", rows.len()));
        }
        for (t, row) in rows.iter().enumerate() {
            if row.len() != n_data {
                return Err(format!(
                    "pstate state {s} row {t} has {} entries",
                    row.len()
                ));
            }
            for (j, &v) in row.iter().enumerate() {
                pstate[[t, j, s]] = v;
            }
        }
    }
    Ok(pstate)
}

/// A column of the expected `newdata` frame as labels: the level strings of
/// the `aggregate` column or the numbers of a named `by` variable.
fn newdata_labels(column: &Value) -> Result<Vec<String>, String> {
    column
        .as_array()
        .ok_or("newdata column is not an array")?
        .iter()
        .map(|item| match item {
            Value::String(label) => Ok(label.clone()),
            other => Ok(r_number_label(num(other)?)),
        })
        .collect()
}

fn check_aggregate_newdata(
    actual: Option<&AggregateGroups>,
    expected: &Value,
) -> Result<(), String> {
    let Some(frame) = expected.as_object() else {
        return match actual {
            None => Ok(()),
            Some(groups) => Err(format!("newdata: expected none, got {groups:?}")),
        };
    };
    let actual = actual.ok_or("newdata: expected a frame, got none")?;
    let columns = frame["columns"]
        .as_object()
        .ok_or("newdata without columns")?;
    if actual.names.len() != columns.len() || actual.names.iter().any(|n| !columns.contains_key(n))
    {
        return Err(format!(
            "newdata columns {:?} != {:?}",
            actual.names,
            columns.keys().collect::<Vec<_>>()
        ));
    }
    let n_groups = frame["nrow"].as_u64().unwrap_or(0) as usize;
    if actual.labels.len() != n_groups {
        return Err(format!(
            "newdata: {} groups, expected {n_groups}",
            actual.labels.len()
        ));
    }
    for (k, name) in actual.names.iter().enumerate() {
        let labels = newdata_labels(&columns[name])?;
        let got: Vec<&str> = actual.labels.iter().map(|row| row[k].as_str()).collect();
        if got != labels.iter().map(String::as_str).collect::<Vec<_>>() {
            return Err(format!("newdata.{name}: {got:?} != {labels:?}"));
        }
    }
    Ok(())
}

#[test]
fn r_fixtures_aggregate_survfit() {
    let topic = "km-aggregate_survfit";
    let doc = load_topic(topic);
    let mut report = Report::new(topic);
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let args = &case["args"];
        let expected = &case["expected"];
        let aspects: Vec<&str> = ["surv", "pstate"]
            .into_iter()
            .filter(|aspect| !expected[*aspect].is_null())
            .chain(std::iter::once("newdata"))
            .collect();
        let result = (|| {
            let surv = match &args["surv"] {
                Value::Null => None,
                value => {
                    let rows = matrix(value)?;
                    let n_data = rows.first().map_or(0, Vec::len);
                    let flat: Vec<f64> = rows.iter().flatten().copied().collect();
                    Some(
                        Array2::from_shape_vec((rows.len(), n_data), flat)
                            .map_err(|err| err.to_string())?,
                    )
                }
            };
            let pstate = match &args["pstate"] {
                Value::Null => None,
                value => Some(aggregate_pstate(value)?),
            };
            let by = aggregate_by(args)?;
            let fun = AggregateFun::parse(text(&args["fun"]).unwrap_or("mean"))
                .map_err(|err| err.to_string())?;
            aggregate_survfit(surv.as_ref(), pstate.as_ref(), &by, fun)
                .map_err(|err| format!("aggregate_survfit: {err}"))
        })();
        let result = match result {
            Ok(result) => result,
            Err(message) => {
                for aspect in &aspects {
                    report.record(name, aspect, Err(message.clone()));
                }
                continue;
            }
        };
        for aspect in &aspects {
            let check = match *aspect {
                "surv" => (|| {
                    let surv = result.surv.as_ref().ok_or("no surv in the result")?;
                    if expected["surv"][0].is_array() {
                        assert_matrix(surv, &matrix(&expected["surv"])?, RTOL_COEF, "surv")
                    } else {
                        // no `by`: R drops the group dimension
                        let flat: Vec<f64> = surv
                            .iter()
                            .map(|row| {
                                (row.len() == 1)
                                    .then(|| row[0])
                                    .ok_or_else(|| format!("surv has {} groups", row.len()))
                            })
                            .collect::<Result<_, _>>()?;
                        assert_vec(&flat, &nums(&expected["surv"])?, RTOL_COEF, "surv")
                    }
                })(),
                "pstate" => (|| {
                    let pstate = result.pstate.as_ref().ok_or("no pstate in the result")?;
                    if expected["pstate"][0][0].is_array() {
                        // one time x group matrix per state
                        for (s, per_state) in expected["pstate"]
                            .as_array()
                            .ok_or("pstate")?
                            .iter()
                            .enumerate()
                        {
                            let actual: Vec<Vec<f64>> = pstate
                                .iter()
                                .map(|by_group| by_group.iter().map(|row| row[s]).collect())
                                .collect();
                            assert_matrix(
                                &actual,
                                &matrix(per_state)?,
                                RTOL_COEF,
                                &format!("pstate[{s}]"),
                            )?;
                        }
                        Ok(())
                    } else {
                        let actual: Vec<Vec<f64>> = pstate
                            .iter()
                            .map(|by_group| {
                                (by_group.len() == 1)
                                    .then(|| by_group[0].clone())
                                    .ok_or_else(|| format!("pstate has {} groups", by_group.len()))
                            })
                            .collect::<Result<_, _>>()?;
                        assert_matrix(&actual, &matrix(&expected["pstate"])?, RTOL_COEF, "pstate")
                    }
                })(),
                _ => check_aggregate_newdata(result.newdata.as_ref(), &expected["newdata"]),
            };
            report.record(name, aspect, check);
        }
    }
    report.finish();
}

// ---------------------------------------------------------------------------
// coxph  [cox]: the fit, its residuals, predictions and survival curves,
// cox.zph, coxph.detail, cch and clogit
// ---------------------------------------------------------------------------

struct CoxCase {
    fit: CoxPHFit,
    names: Vec<String>,
    /// Design columns of each model term, in formula order.
    assign: Vec<Vec<usize>>,
    frame: Frame,
    formula: String,
}

/// Columns of each `+`-separated model term, matched against the design
/// column names (a factor contributes one column per non-reference level).
fn term_assign(formula: &str, names: &[String]) -> Vec<Vec<usize>> {
    let mut assign = Vec::new();
    let mut next = 0;
    for term in rhs_terms(formula) {
        if term == "1"
            || term.starts_with("strata(")
            || term.starts_with("offset(")
            || term.starts_with("cluster(")
        {
            continue;
        }
        let mut columns = Vec::new();
        while next < names.len() && names[next].starts_with(&term) {
            columns.push(next);
            next += 1;
            if names[next - 1] == term {
                break;
            }
        }
        if !columns.is_empty() {
            assign.push(columns);
        }
    }
    assign
}

/// Cluster codes of `cluster(col)` in the formula, R's `match(x, unique(x))`.
fn cluster_codes(formula: &str, frame: &Frame, rows: &[usize]) -> Result<Option<Vec<i32>>, String> {
    let Some(term) = rhs_terms(formula)
        .into_iter()
        .find(|term| term.starts_with("cluster("))
    else {
        return Ok(None);
    };
    let inner = term
        .strip_prefix("cluster(")
        .and_then(|t| t.strip_suffix(')'))
        .ok_or("malformed cluster term")?;
    Ok(Some(column_codes(frame.get(inner)?, rows)))
}

fn column_codes(column: &Column, rows: &[usize]) -> Vec<i32> {
    let mut seen: Vec<String> = Vec::new();
    rows.iter()
        .map(|&i| {
            let label = column.label(i).unwrap_or_default();
            match seen.iter().position(|s| *s == label) {
                Some(p) => p as i32,
                None => {
                    seen.push(label);
                    (seen.len() - 1) as i32
                }
            }
        })
        .collect()
}

fn cox_fit_for_case(doc: &Value, case: &Value) -> Result<CoxCase, String> {
    let frame = case_frame(doc, case)?;
    let formula = text(&case["formula"]).ok_or("no formula")?;
    let args = &case["args"];
    if !args["tt"].is_null() {
        return unsupported("coxph argument tt (time-transform terms)");
    }
    let control = &args["control"];
    let response = response(formula, &frame)?;
    let design = design(formula, &frame)?;
    let weights = arg_nums(case, "weights");
    let rows = complete_rows(&response, &design, &[weights.as_deref()]);
    let nvar = design.names.len();
    let x = Array2::from_shape_vec(
        (rows.len(), nvar),
        rows.iter().flat_map(|&i| design.rows[i].clone()).collect(),
    )
    .map_err(|err| err.to_string())?;
    let data = CoxphData::try_new(
        pick(&response.time, &rows),
        response.start.as_ref().map(|s| pick(s, &rows)),
        pick(&response.status, &rows),
        x,
        weights.as_ref().map(|w| pick(w, &rows)),
        design.strata.as_ref().map(|s| pick(s, &rows)),
        design.offset.as_ref().map(|o| pick(o, &rows)),
    )
    .map_err(|err| format!("coxph data: {err}"))?;
    // R's robust default: a cluster term, an id with repeated events, or
    // fractional weights; `robust = TRUE` without either clusters on rows.
    let mut cluster = cluster_codes(formula, &frame, &rows)?;
    let robust_arg = args["robust"].as_bool();
    if cluster.is_none()
        && let Some(id) = text(&args["id"])
        && robust_arg == Some(true)
    {
        cluster = Some(column_codes(frame.get(id)?, &rows));
    }
    let fractional = weights
        .as_ref()
        .is_some_and(|w| w.iter().any(|v| v.fract() != 0.0));
    let robust = robust_arg.or_else(|| (cluster.is_some() || fractional).then_some(true));
    let defaults = CoxphOptions::default();
    let options = CoxphOptions {
        method: TieMethod::parse(text(&args["ties"])).map_err(|err| err.to_string())?,
        init: arg_nums(case, "init"),
        iter_max: control["iter.max"]
            .as_u64()
            .map_or(defaults.iter_max, |v| v as usize),
        eps: control["eps"].as_f64().unwrap_or(defaults.eps),
        toler_chol: control["toler.chol"]
            .as_f64()
            .unwrap_or(defaults.toler_chol),
        // R's default nocenter = c(-1, 0, 1); `nocenter = NULL` centres every column.
        nocenter: if args.as_object().is_some_and(|o| o.contains_key("nocenter")) {
            None
        } else {
            defaults.nocenter
        },
        cluster,
        robust,
    };
    let fit = CoxPHFit::fit(data, options).map_err(|err| format!("coxph: {err}"))?;
    Ok(CoxCase {
        fit,
        assign: term_assign(formula, &design.names),
        names: design.names,
        frame,
        formula: formula.to_string(),
    })
}

const COX_CORE_ASPECTS: &[&str] = &[
    "coef",
    "coef_names",
    "var",
    "naive_var",
    "loglik",
    "score",
    "iter",
    "n",
    "nevent",
    "means",
    "linear_predictors",
    "wald_test",
    "residuals.martingale",
    "residuals.deviance",
    "wtest",
];

fn check_cox_aspect(cox: &CoxCase, expected: &Value, aspect: &str) -> Result<(), String> {
    let fit = &cox.fit;
    match aspect {
        "coef" => assert_vec(
            &fit.coefficients,
            &named_values(&expected["coef"], &expected["coef_names"])?,
            RTOL_COEF,
            "coef",
        ),
        "coef_names" => {
            let r_names = names_of(&expected["coef_names"]);
            if cox
                .names
                .iter()
                .map(String::as_str)
                .ne(r_names.iter().copied())
            {
                return Err(format!("coef names {:?} != {:?}", cox.names, r_names));
            }
            Ok(())
        }
        "var" => assert_matrix(&fit.var_rows(), &matrix(&expected["var"])?, RTOL_VAR, "var"),
        "naive_var" => match (&fit.naive_var, expected["naive_var"].is_null()) {
            (None, true) => Ok(()),
            (Some(naive), false) => assert_matrix(
                &naive.outer_iter().map(|r| r.to_vec()).collect::<Vec<_>>(),
                &matrix(&expected["naive_var"])?,
                RTOL_VAR,
                "naive_var",
            ),
            (None, false) => Err("R used a robust variance, the fit did not".to_string()),
            (Some(_), true) => Err("the fit used a robust variance, R did not".to_string()),
        },
        "loglik" => {
            let expected = nums(&expected["loglik"])?;
            // A null model reports one log likelihood.
            let actual = if expected.len() == 1 {
                vec![fit.loglik[0]]
            } else {
                fit.loglik.to_vec()
            };
            assert_vec(&actual, &expected, RTOL_COEF, "loglik")
        }
        "score" => {
            if expected["score"].is_null() {
                return Ok(());
            }
            assert_scalar(fit.score, num(&expected["score"])?, RTOL_VAR, "score")
        }
        "iter" => {
            let expected = nums(&expected["iter"])?;
            if expected.is_empty() {
                return Ok(());
            }
            assert_scalar(fit.iter as f64, expected[0], 0.0, "iter")
        }
        "n" => assert_scalar(fit.n as f64, num(&expected["n"])?, 0.0, "n"),
        "nevent" => assert_scalar(fit.nevent as f64, num(&expected["nevent"])?, 0.0, "nevent"),
        "means" => assert_vec(&fit.means, &nums(&expected["means"])?, RTOL_COEF, "means"),
        "linear_predictors" => assert_vec(
            &fit.linear_predictors,
            &nums(&expected["linear_predictors"])?,
            RTOL_COEF,
            "linear_predictors",
        ),
        "wald_test" => {
            if expected["wald_test"].is_null() {
                return Ok(());
            }
            assert_scalar(
                fit.wald_test,
                num(&expected["wald_test"])?,
                RTOL_VAR,
                "wald_test",
            )
        }
        "residuals.martingale" => {
            let expected = &expected["residuals"]["martingale"];
            if is_r_error(expected) {
                return Ok(());
            }
            assert_vec(&fit.residuals, &nums(expected)?, RTOL_COEF, "martingale")
        }
        "residuals.deviance" => {
            let expected = &expected["residuals"]["deviance"];
            if is_r_error(expected) {
                return Ok(());
            }
            let actual = residual_vector(fit, ResidualType::Deviance)?;
            assert_vec(&actual, &nums(expected)?, RTOL_COEF, "deviance")
        }
        "wtest" => {
            let expected = &expected["wtest"];
            if is_r_error(expected) || expected.is_null() {
                return Ok(());
            }
            let wtest = coxph_wtest_py(fit.var_rows(), vec![fit.coefficients_or_zero()], 1e-9)
                .map_err(|err| format!("{err:?}"))?;
            let expected_test = match num(&expected["test"]) {
                Ok(value) => value,
                Err(_) => matrix(&expected["test"])?[0][0],
            };
            assert_scalar(wtest.test[0], expected_test, RTOL_VAR, "wtest.test")?;
            assert_scalar(wtest.df as f64, num(&expected["df"])?, 0.0, "wtest.df")?;
            let solve: Vec<f64> = wtest.solve.iter().map(|row| row[0]).collect();
            // A single coefficient is stored as a 1 x 1 matrix.
            let expected_solve = match nums(&expected["solve"]) {
                Ok(values) => values,
                Err(_) => matrix(&expected["solve"])?.into_iter().flatten().collect(),
            };
            assert_vec(&solve, &expected_solve, RTOL_VAR, "wtest.solve")
        }
        other => unsupported(format!("aspect {other}")),
    }
}

impl CoxPHFit {
    fn var_rows(&self) -> Vec<Vec<f64>> {
        self.var.outer_iter().map(|row| row.to_vec()).collect()
    }
}

fn residual_vector(fit: &CoxPHFit, kind: ResidualType) -> Result<Vec<f64>, String> {
    match fit.residuals(kind, None, None, None) {
        Ok(Residuals::Vector(values)) => Ok(values),
        Ok(Residuals::Matrix(_)) => Err("expected a residual vector".to_string()),
        Err(err) => Err(format!("{err}")),
    }
}

fn residual_matrix(
    fit: &CoxPHFit,
    kind: ResidualType,
    assign: &[Vec<usize>],
) -> Result<Vec<Vec<f64>>, String> {
    match fit.residuals(kind, None, None, Some(assign)) {
        Ok(Residuals::Matrix(values)) => Ok(values.outer_iter().map(|r| r.to_vec()).collect()),
        Ok(Residuals::Vector(_)) => Err("expected a residual matrix".to_string()),
        Err(err) => Err(format!("{err}")),
    }
}

#[test]
fn r_fixtures_coxph() {
    let doc = load_topic("coxph");
    let mut report = Report::new("coxph");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        if !case["formulas"].is_null() {
            continue;
        }
        let expected = &case["expected"];
        match cox_fit_for_case(&doc, case) {
            Err(message) => {
                for aspect in COX_CORE_ASPECTS {
                    report.record(name, aspect, Err(message.clone()));
                }
            }
            Ok(cox) => {
                for aspect in COX_CORE_ASPECTS {
                    if aspect.starts_with("residuals.") && expected["residuals"].is_null() {
                        continue;
                    }
                    if *aspect == "linear_predictors" && expected["linear_predictors"].is_null() {
                        continue;
                    }
                    report.record(name, aspect, check_cox_aspect(&cox, expected, aspect));
                }
            }
        }
    }
    report.finish();
}

const COX_DIAGNOSTIC_RESIDUALS: &[&str] = &[
    "score",
    "schoenfeld",
    "scaledsch",
    "dfbeta",
    "dfbetas",
    "partial",
];

/// The `detail` aspects of `coxph_diagnostics`.
const COX_DETAIL_ASPECTS: &[&str] = &[
    "time", "nevent", "nrisk", "hazard", "varhaz", "wtrisk", "score", "means", "imat",
];

fn check_detail(cox: &CoxCase, expected: &Value, aspect: &str) -> Result<(), String> {
    let detail = coxph_detail(&cox.fit, false).map_err(|err| format!("{err}"))?;
    let nvar = cox.fit.nvar();
    match aspect {
        "time" => assert_vec(&detail.time, &nums(&expected["time"])?, RTOL_COEF, "time"),
        "nevent" => assert_vec(
            &detail.nevent.iter().map(|&v| v as f64).collect::<Vec<_>>(),
            &nums(&expected["nevent"])?,
            0.0,
            "nevent",
        ),
        "nrisk" => assert_vec(
            &detail.nrisk.iter().map(|&v| v as f64).collect::<Vec<_>>(),
            &nums(&expected["nrisk"])?,
            0.0,
            "nrisk",
        ),
        "hazard" => assert_vec(
            &detail.hazard,
            &nums(&expected["hazard"])?,
            RTOL_COEF,
            "hazard",
        ),
        "varhaz" => assert_vec(
            &detail.varhaz,
            &nums(&expected["varhaz"])?,
            RTOL_VAR,
            "varhaz",
        ),
        "wtrisk" => assert_vec(
            &detail.wtrisk,
            &nums(&expected["wtrisk"])?,
            RTOL_COEF,
            "wtrisk",
        ),
        "score" | "means" => {
            let actual = if aspect == "score" {
                &detail.score
            } else {
                &detail.means
            };
            let expected = &expected[aspect];
            if nvar == 1 {
                let flat: Vec<f64> = actual.iter().map(|row| row[0]).collect();
                assert_vec(&flat, &nums(expected)?, RTOL_COEF, aspect)
            } else {
                assert_matrix(actual, &matrix(expected)?, RTOL_COEF, aspect)
            }
        }
        "imat" => {
            let expected = &expected["imat"];
            if nvar == 1 {
                let flat: Vec<f64> = detail.imat.iter().map(|block| block[0][0]).collect();
                assert_vec(&flat, &nums(expected)?, RTOL_VAR, "imat")
            } else {
                // A list of nvar x nvar matrices along the death times.
                let blocks = expected.as_array().ok_or("imat is not a list")?;
                if blocks.len() != detail.imat.len() {
                    return Err(format!(
                        "imat: {} death times, expected {}",
                        detail.imat.len(),
                        blocks.len()
                    ));
                }
                for (g, block) in blocks.iter().enumerate() {
                    assert_matrix(
                        &detail.imat[g],
                        &matrix(block)?,
                        RTOL_VAR,
                        &format!("imat[{g}]"),
                    )?;
                }
                Ok(())
            }
        }
        other => unsupported(format!("detail aspect {other}")),
    }
}

fn check_zph(cox: &CoxCase, expected: &Value, transform: &str, terms: bool) -> Result<(), String> {
    let zph = cox_zph(
        &cox.fit,
        ZphTransform::parse(transform).map_err(|err| format!("{err}"))?,
        terms,
        false,
        true,
        Some(&cox.assign),
    )
    .map_err(|err| format!("{err}"))?;
    let table = matrix(&expected["table"]["values"])?;
    let mut rows: Vec<&CoxZphTest> = zph.table.iter().collect();
    if let Some(global) = &zph.global_test {
        rows.push(global);
    }
    if rows.len() != table.len() {
        return Err(format!(
            "table: {} rows, expected {}",
            rows.len(),
            table.len()
        ));
    }
    for (row, expected) in rows.iter().zip(&table) {
        assert_scalar(row.chisq, expected[0], RTOL_VAR, "table.chisq")?;
        assert_scalar(row.df as f64, expected[1], 0.0, "table.df")?;
        assert_scalar(row.p, expected[2], RTOL_VAR, "table.p")?;
    }
    assert_vec(&zph.time, &nums(&expected["time"])?, RTOL_COEF, "time")?;
    assert_vec(&zph.x, &nums(&expected["x"])?, RTOL_COEF, "x")?;
    assert_matrix(&zph.y, &matrix(&expected["y"])?, RTOL_VAR, "y")?;
    assert_matrix(&zph.var, &matrix(&expected["var"])?, RTOL_VAR, "var")?;
    if text(&expected["transform"]) != Some(zph.transform.as_str()) {
        return Err(format!(
            "transform {} != {:?}",
            zph.transform, expected["transform"]
        ));
    }
    Ok(())
}

#[test]
fn r_fixtures_coxph_diagnostics() {
    let doc = load_topic("coxph_diagnostics");
    let mut report = Report::new("coxph_diagnostics");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"];
        let cox = cox_fit_for_case(&doc, case);
        for kind in COX_DIAGNOSTIC_RESIDUALS {
            let value = &expected["residuals"][kind];
            if value.is_null() || is_r_error(value) {
                continue;
            }
            let aspect = format!("residuals.{kind}");
            let result = match &cox {
                Err(message) => Err(message.clone()),
                Ok(cox) => (|| {
                    let residual_type =
                        ResidualType::parse(kind).map_err(|err| format!("{err}"))?;
                    let actual = residual_matrix(&cox.fit, residual_type, &cox.assign)?;
                    let expected_matrix = if value.is_object() {
                        matrix(&value["values"])?
                    } else {
                        matrix(value)?
                    };
                    let rtol = if matches!(*kind, "scaledsch" | "dfbetas") {
                        RTOL_VAR
                    } else {
                        RTOL_COEF
                    };
                    assert_matrix(&actual, &expected_matrix, rtol, kind)
                })(),
            };
            report.record(name, &aspect, result);
        }
        let detail = &expected["detail"];
        if !detail.is_null() && !is_r_error(detail) {
            for aspect in COX_DETAIL_ASPECTS {
                let result = match &cox {
                    Err(message) => Err(message.clone()),
                    Ok(cox) => check_detail(cox, detail, aspect),
                };
                report.record(name, &format!("detail.{aspect}"), result);
            }
        }
        if let Some(variants) = expected["zph"].as_object() {
            for (key, value) in variants {
                if is_r_error(value) {
                    continue;
                }
                let (transform, terms) = key
                    .rsplit_once('_')
                    .map(|(t, flag)| (t, flag == "terms"))
                    .ok_or("zph key")
                    .expect("zph key has the form transform_terms");
                let result = match &cox {
                    Err(message) => Err(message.clone()),
                    Ok(cox) => check_zph(cox, value, transform, terms),
                };
                report.record(name, &format!("zph.{key}"), result);
            }
        }
    }
    report.finish();
}

/// New data of a `coxph_predict` case as a design matrix (with the training
/// factor levels) plus strata codes and offsets.
struct NewDataDesign {
    x: Vec<Vec<f64>>,
    strata: Option<Vec<i32>>,
    offset: Option<Vec<f64>>,
}

fn newdata_design(cox: &CoxCase, newdata: &Value) -> Result<NewDataDesign, String> {
    let mut frame = inline_frame(newdata)?;
    // Factor levels of the training frame apply to newdata; a numeric
    // column under factor() becomes a factor with the training levels.
    for term in rhs_terms(&cox.formula) {
        let column = term
            .strip_prefix("factor(")
            .and_then(|t| t.strip_suffix(')'))
            .unwrap_or(&term);
        let Ok(training) = cox.frame.get(column) else {
            continue;
        };
        let Ok(new_column) = frame.get(column) else {
            continue;
        };
        match (training, new_column) {
            (Column::Str(_, levels), Column::Str(..)) => frame.set_levels(column, levels.clone()),
            (Column::Num(_), Column::Num(values)) if term.starts_with("factor(") => {
                let labels: Vec<Option<String>> =
                    values.iter().map(|&v| Some(format_r_number(v))).collect();
                let levels = training.levels();
                if let Some((_, slot)) = frame.columns.iter_mut().find(|(name, _)| name == column) {
                    *slot = Column::Str(labels, levels);
                }
            }
            _ => {}
        }
    }
    let design = design(&cox.formula, &frame)?;
    if design.names != cox.names {
        return Err(format!(
            "newdata columns {:?} != model columns {:?}",
            design.names, cox.names
        ));
    }
    // Strata codes come from the training levels.
    let strata = match rhs_terms(&cox.formula)
        .into_iter()
        .find(|term| term.starts_with("strata("))
    {
        Some(term) => {
            let inner = term
                .strip_prefix("strata(")
                .and_then(|t| t.strip_suffix(')'))
                .ok_or("strata term")?;
            let training = cox.frame.get(inner)?;
            let levels = training.levels();
            let column = frame.get(inner)?;
            Some(
                (0..column.len())
                    .map(|i| {
                        column
                            .label(i)
                            .and_then(|label| levels.iter().position(|l| *l == label))
                            .map(|p| p as i32)
                            .ok_or_else(|| "newdata stratum not in the fit".to_string())
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            )
        }
        None => None,
    };
    Ok(NewDataDesign {
        x: design.rows,
        strata,
        offset: design.offset,
    })
}

fn newdata_for(cox: &CoxCase, design: &NewDataDesign) -> Result<CoxNewData, String> {
    let nvar = cox.fit.nvar();
    let x = Array2::from_shape_vec(
        (design.x.len(), nvar),
        design.x.iter().flatten().copied().collect(),
    )
    .map_err(|err| err.to_string())?;
    CoxNewData::try_new(x, design.strata.clone(), design.offset.clone(), None, None)
        .map_err(|err| format!("{err}"))
}

fn check_prediction(
    actual: &CoxPrediction,
    expected: &Value,
    rtol: f64,
    path: &str,
) -> Result<(), String> {
    assert_vec(
        &actual.fit,
        &nums(&expected["fit"])?,
        rtol,
        &format!("{path}.fit"),
    )?;
    if let Some(se) = &actual.se_fit {
        assert_vec(
            se,
            &nums(&expected["se_fit"])?,
            RTOL_VAR,
            &format!("{path}.se_fit"),
        )?;
    }
    Ok(())
}

fn check_predict(
    cox: &CoxCase,
    expected: &Value,
    newdata: Option<&CoxNewData>,
) -> Vec<(String, Result<(), String>)> {
    let mut results = Vec::new();
    let fit = &cox.fit;
    for kind in [
        "lp",
        "risk",
        "expected",
        "terms",
        "survival",
        "lp_uncentered",
    ] {
        let value = &expected[kind];
        if value.is_null() || is_r_error(value) {
            continue;
        }
        let result = (|| match kind {
            "lp" => check_prediction(
                &fit.predict_lp(newdata, true, PredictReference::Strata)
                    .map_err(|err| format!("{err}"))?,
                value,
                RTOL_COEF,
                "lp",
            ),
            "risk" => check_prediction(
                &fit.predict_risk(newdata, true, PredictReference::Strata)
                    .map_err(|err| format!("{err}"))?,
                value,
                RTOL_COEF,
                "risk",
            ),
            "expected" => check_prediction(
                &fit.predict_expected(newdata, true)
                    .map_err(|err| format!("{err}"))?,
                value,
                RTOL_COEF,
                "expected",
            ),
            "survival" => check_prediction(
                &fit.predict_survival(newdata, true)
                    .map_err(|err| format!("{err}"))?,
                value,
                RTOL_COEF,
                "survival",
            ),
            "terms" => {
                let terms = fit
                    .predict_terms(newdata, true, PredictReference::Sample, &cox.assign)
                    .map_err(|err| format!("{err}"))?;
                let expected_fit = if cox.assign.len() == 1 && !value["fit"][0].is_array() {
                    nums(&value["fit"])?.into_iter().map(|v| vec![v]).collect()
                } else {
                    matrix(&value["fit"])?
                };
                assert_matrix(&terms.fit, &expected_fit, RTOL_COEF, "terms.fit")?;
                let expected_se = if cox.assign.len() == 1 && !value["se_fit"][0].is_array() {
                    nums(&value["se_fit"])?
                        .into_iter()
                        .map(|v| vec![v])
                        .collect()
                } else {
                    matrix(&value["se_fit"])?
                };
                assert_matrix(
                    terms.se_fit.as_ref().ok_or("no se")?,
                    &expected_se,
                    RTOL_VAR,
                    "terms.se_fit",
                )?;
                if !value["constant"].is_null() {
                    assert_scalar(
                        terms.constant,
                        num(&value["constant"])?,
                        RTOL_COEF,
                        "terms.constant",
                    )?;
                }
                Ok(())
            }
            "lp_uncentered" => {
                let lp = fit
                    .predict_lp(newdata, false, PredictReference::Zero)
                    .map_err(|err| format!("{err}"))?;
                assert_vec(&lp.fit, &nums(value)?, RTOL_COEF, "lp_uncentered")
            }
            _ => unreachable!(),
        })();
        results.push((kind.to_string(), result));
    }
    results
}

/// `survfit` curves: `n`, `time`, `n_risk`, `n_event`, `n_censor`, `surv`,
/// `cumhaz`, `std_err` per curve.  Confidence limits are not produced by
/// the Rust curves and are skipped.
fn check_survfit(curves: &[CoxSurvfitCurve], expected: &Value, path: &str) -> Result<(), String> {
    let expected_curves = expected["curves"].as_array().ok_or("no curves")?;
    if curves.len() != expected_curves.len() {
        return Err(format!(
            "{path}: {} curves, expected {}",
            curves.len(),
            expected_curves.len()
        ));
    }
    let n = nums(&expected["n"])?;
    for (k, (curve, expected)) in curves.iter().zip(expected_curves).enumerate() {
        let name = format!("{path}[{k}]");
        assert_scalar(
            curve.n as f64,
            n[k.min(n.len() - 1)],
            0.0,
            &format!("{name}.n"),
        )?;
        assert_vec(
            &curve.time,
            &nums(&expected["time"])?,
            RTOL_COEF,
            &format!("{name}.time"),
        )?;
        assert_vec(
            &curve.n_risk,
            &nums(&expected["n_risk"])?,
            RTOL_COEF,
            &format!("{name}.n_risk"),
        )?;
        assert_vec(
            &curve.n_event,
            &nums(&expected["n_event"])?,
            RTOL_COEF,
            &format!("{name}.n_event"),
        )?;
        assert_vec(
            &curve.n_censor,
            &nums(&expected["n_censor"])?,
            RTOL_COEF,
            &format!("{name}.n_censor"),
        )?;
        let columns = curve.surv.first().map_or(1, Vec::len);
        let expected_matrix = |key: &str| -> Result<Vec<Vec<f64>>, String> {
            let value = &expected[key];
            if columns == 1 && !value[0].is_array() {
                Ok(nums(value)?.into_iter().map(|v| vec![v]).collect())
            } else {
                matrix(value)
            }
        };
        assert_matrix(
            &curve.surv,
            &expected_matrix("surv")?,
            RTOL_COEF,
            &format!("{name}.surv"),
        )?;
        assert_matrix(
            &curve.cumhaz,
            &expected_matrix("cumhaz")?,
            RTOL_COEF,
            &format!("{name}.cumhaz"),
        )?;
        if let Some(std_err) = &curve.std_err {
            assert_matrix(
                std_err,
                &expected_matrix("std_err")?,
                RTOL_VAR,
                &format!("{name}.std_err"),
            )?;
        }
    }
    Ok(())
}

#[test]
fn r_fixtures_coxph_predict() {
    let doc = load_topic("coxph_predict");
    let mut report = Report::new("coxph_predict");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"];
        let cox = match cox_fit_for_case(&doc, case) {
            Ok(cox) => cox,
            Err(message) => {
                report.record(name, "fit", Err(message));
                continue;
            }
        };
        let fit = &cox.fit;
        for (aspect, centered) in [("basehaz_centered", true), ("basehaz_uncentered", false)] {
            let value = &expected[aspect];
            if value.is_null() || is_r_error(value) {
                continue;
            }
            let result = (|| {
                let basehaz = fit.basehaz(centered).map_err(|err| format!("{err}"))?;
                assert_vec(&basehaz.time, &nums(&value["time"])?, RTOL_COEF, "time")?;
                assert_vec(
                    &basehaz.hazard,
                    &nums(&value["hazard"])?,
                    RTOL_COEF,
                    "hazard",
                )?;
                if let Some(strata) = &basehaz.strata {
                    let expected_strata = value["strata"]
                        .as_array()
                        .ok_or("basehaz strata")?
                        .iter()
                        .map(|v| v.as_str().unwrap_or("").to_string())
                        .collect::<Vec<_>>();
                    let levels = strata_levels(&cox)?;
                    let actual: Vec<String> = strata
                        .iter()
                        .map(|&code| levels[code as usize].clone())
                        .collect();
                    if actual != expected_strata {
                        return Err(format!("basehaz strata {actual:?} != {expected_strata:?}"));
                    }
                }
                Ok(())
            })();
            report.record(name, aspect, result);
        }
        for (aspect, options) in [
            ("survfit", SurvfitOptions::default()),
            (
                "survfit_censor_false",
                SurvfitOptions {
                    censor: false,
                    ..SurvfitOptions::default()
                },
            ),
            (
                "survfit_stype2",
                SurvfitOptions {
                    stype: 2,
                    ctype: Some(1),
                    ..SurvfitOptions::default()
                },
            ),
            (
                "survfit_ctype2",
                SurvfitOptions {
                    stype: 2,
                    ctype: Some(2),
                    ..SurvfitOptions::default()
                },
            ),
        ] {
            let value = &expected[aspect];
            if value.is_null() || is_r_error(value) {
                continue;
            }
            let result = fit
                .survfit(None, options)
                .map_err(|err| format!("{err}"))
                .and_then(|curves| check_survfit(&curves, value, aspect));
            report.record(name, aspect, result);
        }
        for (kind, result) in check_predict(&cox, &expected["predict"], None) {
            report.record(name, &format!("predict.{kind}"), result);
        }
        if expected["newdata"].is_null() {
            continue;
        }
        let newdata =
            newdata_design(&cox, &expected["newdata"]).and_then(|d| newdata_for(&cox, &d));
        match newdata {
            Err(message) => {
                report.record(name, "newdata", Err(message));
            }
            Ok(newdata) => {
                for (kind, result) in
                    check_predict(&cox, &expected["predict_newdata"], Some(&newdata))
                {
                    report.record(name, &format!("predict_newdata.{kind}"), result);
                }
                for aspect in ["survfit_newdata", "survfit_newdata_loglog"] {
                    let value = &expected[aspect];
                    if value.is_null() || is_r_error(value) {
                        continue;
                    }
                    let result = fit
                        .survfit(Some(&newdata), SurvfitOptions::default())
                        .map_err(|err| format!("{err}"))
                        .and_then(|curves| check_survfit(&curves, value, aspect));
                    report.record(name, aspect, result);
                }
            }
        }
    }
    report.finish();
}

/// Labels of the strata levels of a case (`sex=1`, `sex=2`, ...).
fn strata_levels(cox: &CoxCase) -> Result<Vec<String>, String> {
    let term = rhs_terms(&cox.formula)
        .into_iter()
        .find(|term| term.starts_with("strata("))
        .ok_or("no strata term")?;
    let inner = term
        .strip_prefix("strata(")
        .and_then(|t| t.strip_suffix(')'))
        .ok_or("strata term")?;
    // survfit.coxph names the strata of a single factor by its levels and
    // those of a numeric variable as `name=value`.
    let column = cox.frame.get(inner)?;
    Ok(column
        .levels()
        .into_iter()
        .map(|level| match column {
            Column::Str(..) => level,
            Column::Num(_) => format!("{inner}={level}"),
        })
        .collect())
}

#[test]
fn r_fixtures_cch() {
    let doc = load_topic("cch");
    let mut report = Report::new("cch");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"];
        let result = (|| -> Result<CchFitResult, String> {
            let frame = case_frame(&doc, case)?;
            let formula = text(&case["formula"]).ok_or("no formula")?;
            let args = &case["args"];
            let response = response(formula, &frame)?;
            let design = design(formula, &frame)?;
            let rows: Vec<usize> = (0..frame.nrow()).collect();
            let subcohort: Vec<i32> = frame
                .get(text(&args["subcoh"]).ok_or("subcoh")?)?
                .numeric("subcoh")?
                .iter()
                .map(|&v| i32::from(v != 0.0))
                .collect();
            let id: Vec<i64> = frame
                .get(text(&args["id"]).ok_or("id")?)?
                .numeric("id")?
                .iter()
                .map(|&v| v as i64)
                .collect();
            let method = text(&args["method"]).ok_or("method")?;
            let names_ok = names_of(&expected["coef_names"])
                .iter()
                .copied()
                .eq(design.names.iter().map(String::as_str));
            if !names_ok {
                return Err(format!(
                    "coef names {:?} != {:?}",
                    design.names,
                    names_of(&expected["coef_names"])
                ));
            }
            let x: Vec<Vec<f64>> = rows.iter().map(|&i| design.rows[i].clone()).collect();
            match text(&args["stratum"]) {
                None => cch_fit(
                    response.time.clone(),
                    response.status.clone(),
                    x,
                    subcohort,
                    id,
                    num(&args["cohort.size"])? as usize,
                    response.start.clone(),
                    method,
                    false,
                )
                .map_err(|err| format!("{err:?}")),
                Some(column) => {
                    let levels = frame.get(column)?.levels();
                    let stratum: Vec<usize> = (0..frame.nrow())
                        .map(|i| {
                            frame
                                .get(column)
                                .ok()
                                .and_then(|c| c.label(i))
                                .and_then(|label| levels.iter().position(|l| *l == label))
                                .unwrap_or(0)
                        })
                        .collect();
                    let sizes: Vec<usize> = nums(&args["cohort.size"])?
                        .iter()
                        .map(|&v| v as usize)
                        .collect();
                    cch_borgan_fit(
                        response.time.clone(),
                        response.status.clone(),
                        x,
                        subcohort,
                        id,
                        stratum,
                        sizes,
                        response.start.clone(),
                        method,
                    )
                    .map_err(|err| format!("{err:?}"))
                }
            }
        })();
        for aspect in [
            "coef",
            "var",
            "naive_var",
            "subcohort_size",
            "cohort_size",
            "method",
        ] {
            let check = match &result {
                Err(message) => Err(message.clone()),
                Ok(fit) => (|| match aspect {
                    "coef" => assert_vec(
                        &fit.coefficients,
                        &named_values(&expected["coef"], &expected["coef_names"])?,
                        RTOL_COEF,
                        "coef",
                    ),
                    "var" => assert_matrix(&fit.var, &matrix(&expected["var"])?, RTOL_VAR, "var"),
                    "naive_var" => assert_matrix(
                        &fit.naive_var,
                        &matrix(&expected["naive_var"])?,
                        RTOL_VAR,
                        "naive_var",
                    ),
                    "subcohort_size" => assert_vec(
                        &fit.subcohort_size
                            .iter()
                            .map(|&v| v as f64)
                            .collect::<Vec<_>>(),
                        &nums(&expected["subcohort_size"])?,
                        0.0,
                        "subcohort_size",
                    ),
                    "cohort_size" => assert_vec(
                        &fit.cohort_size
                            .iter()
                            .map(|&v| v as f64)
                            .collect::<Vec<_>>(),
                        &nums(&expected["cohort_size"])?,
                        0.0,
                        "cohort_size",
                    ),
                    "method" => {
                        if text(&expected["method"]) == Some(fit.method.as_str()) {
                            Ok(())
                        } else {
                            Err(format!("method {} != {:?}", fit.method, expected["method"]))
                        }
                    }
                    _ => unreachable!(),
                })(),
            };
            report.record(name, aspect, check);
        }
    }
    report.finish();
}

#[test]
fn r_fixtures_clogit() {
    let doc = load_topic("clogit");
    let mut report = Report::new("clogit");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"];
        // clogit(case ~ x + strata(s), method) is
        // coxph(Surv(rep(1, n), case) ~ x + strata(s), method), with
        // "approximate" meaning Breslow.
        let result = (|| -> Result<CoxCase, String> {
            let frame = case_frame(&doc, case)?;
            let formula = text(&case["formula"]).ok_or("no formula")?;
            let (lhs, _) = formula.split_once('~').ok_or("formula")?;
            let status = status_column(lhs.trim(), &frame)?;
            let design = design(formula, &frame)?;
            let n = frame.nrow();
            let x = Array2::from_shape_vec(
                (n, design.names.len()),
                design.rows.iter().flatten().copied().collect(),
            )
            .map_err(|err| err.to_string())?;
            let data = CoxphData::try_new(
                vec![1.0; n],
                None,
                status,
                x,
                None,
                design.strata.clone(),
                None,
            )
            .map_err(|err| format!("{err}"))?;
            let method = match text(&case["args"]["method"]) {
                Some("approximate") => TieMethod::Breslow,
                other => TieMethod::parse(other).map_err(|err| format!("{err}"))?,
            };
            let fit = CoxPHFit::fit(
                data,
                CoxphOptions {
                    method,
                    ..CoxphOptions::default()
                },
            )
            .map_err(|err| format!("{err}"))?;
            Ok(CoxCase {
                fit,
                assign: term_assign(formula, &design.names),
                names: design.names,
                frame,
                formula: formula.to_string(),
            })
        })();
        for aspect in [
            "coef",
            "coef_names",
            "var",
            "loglik",
            "iter",
            "score",
            "n",
            "nevent",
            "linear_predictors",
        ] {
            let check = match &result {
                Err(message) => Err(message.clone()),
                Ok(cox) => check_cox_aspect(cox, expected, aspect),
            };
            report.record(name, aspect, check);
        }
    }
    report.finish();
}

// ---------------------------------------------------------------------------
// residual kernels (resid): coxmart / agmart3 / coxscore2 / agscore3 / coxscho
// fed with R's own coefficients, so the kernels are checked independently
// of the Cox fit
// ---------------------------------------------------------------------------

struct ResidualKernelCase {
    response: Response,
    rows: Vec<usize>,
    covariates: ndarray::Array2<f64>,
    score: Vec<f64>,
    weights: Option<Vec<f64>>,
    strata: Option<Vec<i32>>,
    ties: crate::residuals::TieMethod,
    exact: bool,
}

fn residual_kernel_case(doc: &Value, case: &Value) -> Result<ResidualKernelCase, String> {
    use crate::residuals::TieMethod;
    let frame = case_frame(doc, case)?;
    let formula = text(&case["formula"]).ok_or("no formula")?;
    let args = &case["args"];
    let response = response(formula, &frame)?;
    let design = design(formula, &frame)?;
    if design.names.is_empty() {
        return unsupported("null model");
    }
    let weights = arg_nums(case, "weights");
    let rows = complete_rows(&response, &design, &[weights.as_deref()]);
    let coef_names = serde_json::json!(design.names);
    let beta = named_values(&case["expected"]["coef"], &coef_names)
        .map_err(|err| format!("unsupported: harness: {err}"))?;
    let covariates =
        ndarray::Array2::from_shape_fn((rows.len(), beta.len()), |(r, c)| design.rows[rows[r]][c]);
    let score: Vec<f64> = rows
        .iter()
        .enumerate()
        .map(|(r, &i)| {
            let offset = design.offset.as_ref().map_or(0.0, |o| o[i]);
            (covariates.row(r).dot(&ndarray::Array1::from(beta.clone())) + offset).exp()
        })
        .collect();
    let ties = text(&args["ties"]).unwrap_or("efron");
    Ok(ResidualKernelCase {
        rows: rows.clone(),
        covariates,
        score,
        weights: weights.map(|w| pick(&w, &rows)),
        strata: design.strata.as_ref().map(|s| pick(s, &rows)),
        // R's exact fits use the Breslow-type `coxmart2` for the martingale
        // residual and have no score/Schoenfeld residuals.
        ties: if ties == "efron" {
            TieMethod::Efron
        } else {
            TieMethod::Breslow
        },
        exact: ties == "exact",
        response,
    })
}

fn check_residual_kernel(
    case: &ResidualKernelCase,
    expected: &Value,
    kind: &str,
) -> Result<(), String> {
    use crate::core::SurvResponse;
    use crate::data_types::{
        AndersenGillInput, CountingProcessData, CoxMartInput, SurvivalData, Weights,
    };
    let time = pick(&case.response.time, &case.rows);
    let status = pick(&case.response.status, &case.rows);
    let start = case.response.start.as_ref().map(|s| pick(s, &case.rows));
    let weights = case
        .weights
        .clone()
        .map(|w| Weights::try_new(w).map_err(|e| e.to_string()))
        .transpose()?;
    let value = &expected[kind];
    match kind {
        "martingale" => {
            let actual = match &start {
                Some(start) => crate::residuals::agmart(
                    &AndersenGillInput::try_new(
                        CountingProcessData::try_new(start.clone(), time, status)
                            .map_err(|e| e.to_string())?,
                        case.score.clone(),
                        weights,
                        case.strata.clone(),
                    )
                    .map_err(|e| e.to_string())?,
                    case.ties,
                ),
                None => crate::residuals::coxmart(
                    &CoxMartInput::try_new(
                        SurvivalData::try_new(time, status).map_err(|e| e.to_string())?,
                        case.score.clone(),
                        weights,
                        case.strata.clone(),
                    )
                    .map_err(|e| e.to_string())?,
                    case.ties,
                ),
            }
            .map_err(|e| format!("martingale: {e}"))?;
            assert_vec(&actual, &nums(value)?, RTOL_COEF, "martingale")
        }
        "score" => {
            if case.exact {
                return unsupported("score residuals of an exact fit");
            }
            let actual = match &start {
                Some(start) => crate::scoring::agscore3(
                    &CountingProcessData::try_new(start.clone(), time, status)
                        .map_err(|e| e.to_string())?,
                    case.covariates.view(),
                    &case.score,
                    case.weights.as_deref(),
                    case.strata.as_deref(),
                    case.ties,
                ),
                None => crate::scoring::coxscore2(
                    &SurvivalData::try_new(time, status).map_err(|e| e.to_string())?,
                    case.covariates.view(),
                    &case.score,
                    case.weights.as_deref(),
                    case.strata.as_deref(),
                    case.ties,
                ),
            }
            .map_err(|e| format!("score: {e}"))?;
            let actual: Vec<Vec<f64>> = actual.outer_iter().map(|row| row.to_vec()).collect();
            let expected_matrix = if value.is_object() {
                matrix(&value["values"])?
            } else {
                matrix(value)?
            };
            assert_matrix(&actual, &expected_matrix, RTOL_COEF, "score")
        }
        "schoenfeld" => {
            if case.exact {
                return unsupported("Schoenfeld residuals of an exact fit");
            }
            let counting;
            let survival;
            let response = match &start {
                Some(start) => {
                    counting = CountingProcessData::try_new(start.clone(), time, status)
                        .map_err(|e| e.to_string())?;
                    SurvResponse::Counting(&counting)
                }
                None => {
                    survival = SurvivalData::try_new(time, status).map_err(|e| e.to_string())?;
                    SurvResponse::Right(&survival)
                }
            };
            let actual = crate::core::schoenfeld_residuals(
                response,
                case.covariates.view(),
                &case.score,
                case.weights.as_deref(),
                case.strata.as_deref(),
                case.ties,
            )
            .map_err(|e| format!("schoenfeld: {e}"))?;
            let expected_matrix = if value.is_object() {
                assert_vec(&actual.time, &nums(&value["time"])?, 0.0, "schoenfeld.time")?;
                matrix(&value["values"])?
            } else {
                matrix(value)?
            };
            assert_matrix(&actual.residuals, &expected_matrix, RTOL_COEF, "schoenfeld")
        }
        other => unsupported(format!("harness: residual kind {other}")),
    }
}

#[test]
fn r_fixtures_residual_kernels() {
    let doc = load_topic("coxph_diagnostics");
    let mut report = Report::new("residual_kernels");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"]["residuals"];
        let kernel_case = residual_kernel_case(&doc, case);
        for kind in ["martingale", "score", "schoenfeld"] {
            let value = &expected[kind];
            if value.is_null() || is_r_error(value) {
                continue;
            }
            let result = match &kernel_case {
                Err(message) => Err(message.clone()),
                Ok(kernel_case) => check_residual_kernel(kernel_case, expected, kind),
            };
            report.record(name, kind, result);
        }
    }
    report.finish();
}

