#[test]
fn r_fixtures_spline_bases() {
    use crate::core::{nsk_basis, pspline_basis};
    let doc = load_topic("utilities");
    let mut report = Report::new("utilities");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        if name != "nsk_basis" && name != "pspline_basis" {
            continue;
        }
        let expected = &case["expected"];
        for (aspect, value) in expected.as_object().expect("expected object") {
            let result = (|| -> Result<(), String> {
                let x = if name == "nsk_basis" && aspect != "lung_age_df3" {
                    nums(&case["args"]["x"])?
                } else {
                    load_dataset("lung")?.get("age")?.numeric("age")?
                };
                let expected_values = matrix(&value["values"])?;
                if name == "nsk_basis" {
                    // The fixture records the knots nsk settled on; the
                    // call reproduces R's arguments.
                    let (df, knots, boundary) = match aspect.as_str() {
                        "df4" => (Some(4), None, None),
                        "knots_35_50_65" => {
                            (None, Some(vec![35.0, 50.0, 65.0]), Some((20.0, 80.0)))
                        }
                        "df3_intercept" => (Some(3), None, None),
                        "df4_b01" => {
                            let b = nums(&value["boundary_knots"])?;
                            (Some(4), None, Some((b[0], b[1])))
                        }
                        "lung_age_df3" => (Some(3), None, None),
                        other => return unsupported(format!("harness: nsk aspect {other}")),
                    };
                    let intercept = value["intercept"].as_bool().unwrap_or(false);
                    let basis = nsk_basis(&x, df, knots.as_deref(), intercept, boundary)
                        .map_err(|e| format!("nsk: {e}"))?;
                    assert_vec(&basis.knots, &nums(&value["knots"])?, RTOL_COEF, "knots")?;
                    let b = nums(&value["boundary_knots"])?;
                    assert_vec(
                        &[basis.boundary_knots.0, basis.boundary_knots.1],
                        &b,
                        RTOL_COEF,
                        "boundary_knots",
                    )?;
                    let rows: Vec<Vec<f64>> = basis
                        .basis
                        .chunks(basis.n_cols)
                        .map(<[f64]>::to_vec)
                        .collect();
                    assert_matrix(&rows, &expected_values, RTOL_COEF, "values")
                } else {
                    let nterm = num(&value["nterm"])? as usize;
                    let degree = num(&value["degree"])? as usize;
                    let b = nums(&value["boundary_knots"])?;
                    let intercept = value["intercept"].as_bool().unwrap_or(false);
                    let basis = pspline_basis(&x, nterm, degree, (b[0], b[1]))
                        .map_err(|e| format!("pspline: {e}"))?;
                    // R drops the first column when intercept = FALSE.
                    let rows: Vec<Vec<f64>> = basis
                        .basis
                        .iter()
                        .map(|row| row[usize::from(!intercept)..].to_vec())
                        .collect();
                    assert_matrix(&rows, &expected_values, RTOL_COEF, "values")
                }
            })();
            report.record(name, aspect, result);
        }
    }
    report.finish();
}

// ---------------------------------------------------------------------------
// survreg (key: survreg)
// ---------------------------------------------------------------------------

/// A `Surv()` response with `survreg`'s censoring codes (0 right, 1 exact,
/// 2 left, 3 interval), covering the `left`, `interval` and `interval2`
/// types the generic reader does not.
struct SurvregResponse {
    time: Vec<f64>,
    time2: Option<Vec<f64>>,
    status: Vec<i32>,
}

fn survreg_response(formula: &str, frame: &Frame) -> Result<SurvregResponse, String> {
    let lhs = formula.split('~').next().ok_or("formula without ~")?.trim();
    let inner = lhs
        .strip_prefix("Surv(")
        .and_then(|rest| rest.strip_suffix(')'))
        .ok_or_else(|| format!("unsupported: harness: response {lhs:?}"))?;
    let mut args: Vec<&str> = inner.split(',').map(str::trim).collect();
    let surv_type = args
        .iter()
        .position(|arg| arg.starts_with("type"))
        .map(|position| {
            args.remove(position)
                .split_once('=')
                .map(|(_, value)| value.trim().trim_matches('"').to_string())
                .unwrap_or_default()
        })
        .unwrap_or_else(|| "right".to_string());
    match (surv_type.as_str(), args.as_slice()) {
        ("right", _) => {
            let response = response(formula, frame)?;
            if response.start.is_some() {
                return unsupported("counting-process survreg");
            }
            Ok(SurvregResponse {
                time: response.time,
                time2: None,
                status: response.status,
            })
        }
        ("left", [time, event]) => {
            let time = frame.get(time)?.numeric(time)?;
            let (name, threshold) = event
                .split_once('>')
                .ok_or_else(|| format!("unsupported: harness: left event {event:?}"))?;
            let values = frame.get(name.trim())?.numeric(name.trim())?;
            let threshold: f64 = threshold.trim().parse().map_err(|_| "bad threshold")?;
            // Surv(type = "left"): event 1 is exact, 0 is left censored (code 2).
            let status = values
                .iter()
                .map(|&v| if v > threshold { 1 } else { 2 })
                .collect();
            Ok(SurvregResponse {
                time,
                time2: None,
                status,
            })
        }
        ("interval2", [left, right]) => {
            let left = frame.get(left)?.numeric(left)?;
            let right = frame.get(right)?.numeric(right)?;
            let n = left.len();
            let mut time = Vec::with_capacity(n);
            let mut time2 = Vec::with_capacity(n);
            let mut status = Vec::with_capacity(n);
            for i in 0..n {
                let (lo, hi) = (left[i], right[i]);
                let code = if lo.is_nan() {
                    2
                } else if hi.is_nan() {
                    0
                } else if lo == hi {
                    1
                } else {
                    3
                };
                time.push(if code == 2 { hi } else { lo });
                time2.push(if code == 3 { hi } else { 1.0 });
                status.push(code);
            }
            Ok(SurvregResponse {
                time,
                time2: Some(time2),
                status,
            })
        }
        ("interval", [time, time2, event]) => {
            let status: Vec<i32> = frame
                .get(event)?
                .numeric(event)?
                .iter()
                .map(|&v| v as i32)
                .collect();
            let time2 = frame.get(time2)?.numeric(time2)?;
            Ok(SurvregResponse {
                time: frame.get(time)?.numeric(time)?,
                time2: Some(
                    time2
                        .iter()
                        .zip(&status)
                        .map(|(&t, &s)| if s == 3 { t } else { 1.0 })
                        .collect(),
                ),
                status,
            })
        }
        _ => unsupported(format!(
            "harness: Surv(type = {surv_type:?}) with {} arguments",
            args.len()
        )),
    }
}

/// Codes of a `cluster(x)` term, in first-appearance order.
fn survreg_cluster_codes(formula: &str, frame: &Frame) -> Result<Option<Vec<usize>>, String> {
    let Some(term) = rhs_terms(formula)
        .into_iter()
        .find(|term| term.starts_with("cluster("))
    else {
        return Ok(None);
    };
    let inner = term
        .strip_prefix("cluster(")
        .and_then(|t| t.strip_suffix(')'))
        .ok_or("bad cluster term")?;
    let column = frame.get(inner)?;
    let mut labels: Vec<String> = Vec::new();
    let codes = (0..column.len())
        .map(|i| {
            let label = column.label(i).unwrap_or_default();
            match labels.iter().position(|l| *l == label) {
                Some(code) => code,
                None => {
                    labels.push(label);
                    labels.len() - 1
                }
            }
        })
        .collect();
    Ok(Some(codes))
}

/// R's `attr(x, "assign")` for a design built by [`design`]: the term
/// number (0 for the intercept) of every column, from the column names.
fn design_assign(formula: &str, names: &[String]) -> Vec<usize> {
    let terms: Vec<String> = rhs_terms(formula)
        .into_iter()
        .filter(|term| {
            term != "1"
                && !term.starts_with("strata(")
                && !term.starts_with("cluster(")
                && !term.starts_with("offset(")
        })
        .collect();
    names
        .iter()
        .map(|name| {
            if name == "(Intercept)" {
                return 0;
            }
            terms
                .iter()
                .position(|term| name == term || name.starts_with(term.as_str()))
                .map_or(0, |position| position + 1)
        })
        .collect()
}

/// The training frame with the rows of `newdata` appended (columns the new
/// frame lacks become missing), so factor levels come from the training data.
fn append_rows(train: &Frame, extra: &Frame) -> Result<Frame, String> {
    let n = extra.nrow();
    let columns = train
        .columns
        .iter()
        .map(|(name, column)| {
            let appended = match (column, extra.get(name).ok()) {
                (Column::Num(values), Some(Column::Num(new))) => {
                    Column::Num(values.iter().copied().chain(new.iter().copied()).collect())
                }
                (Column::Num(values), Some(Column::Str(new, _))) => Column::Num(
                    values
                        .iter()
                        .copied()
                        .chain(new.iter().map(|v| {
                            v.as_deref()
                                .and_then(|v| v.parse().ok())
                                .unwrap_or(f64::NAN)
                        }))
                        .collect(),
                ),
                (Column::Num(values), None) => Column::Num(
                    values
                        .iter()
                        .copied()
                        .chain(std::iter::repeat_n(f64::NAN, n))
                        .collect(),
                ),
                (Column::Str(values, levels), Some(new)) => Column::Str(
                    values
                        .iter()
                        .cloned()
                        .chain((0..n).map(|i| new.label(i)))
                        .collect(),
                    levels.clone(),
                ),
                (Column::Str(values, levels), None) => Column::Str(
                    values
                        .iter()
                        .cloned()
                        .chain(std::iter::repeat_n(None, n))
                        .collect(),
                    levels.clone(),
                ),
            };
            Ok((name.clone(), appended))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(Frame { columns })
}

/// One `predict`/`predict_newdata` block of the fixture against a prediction.
fn check_survreg_prediction(
    fit: &SurvregFit,
    newdata: Option<&SurvregNewdata<'_>>,
    assign: &[usize],
    kind: &str,
    expected: &Value,
) -> Result<(), String> {
    use crate::regression::survreg_predict::SurvregPredictType;
    let predict_type = SurvregPredictType::parse(kind).map_err(|err| err.to_string())?;
    let p = nums(&expected["p"]).unwrap_or_default();
    let prediction = fit
        .predict(newdata, predict_type, true, &p, Some(assign), None)
        .map_err(|err| format!("predict: {err}"))?;
    let se = prediction.se_fit.as_deref().ok_or("no se.fit")?;
    let path = format!("predict.{kind}");
    match &expected["fit"] {
        Value::Array(rows) if rows.first().is_some_and(Value::is_array) => {
            assert_matrix(
                &prediction.fit,
                &matrix(&expected["fit"])?,
                RTOL_COEF,
                &format!("{path}.fit"),
            )?;
            assert_matrix(
                se,
                &matrix(&expected["se_fit"])?,
                RTOL_VAR,
                &format!("{path}.se_fit"),
            )
        }
        _ => {
            let fit_values: Vec<f64> = prediction.fit.iter().map(|row| row[0]).collect();
            let se_values: Vec<f64> = se.iter().map(|row| row[0]).collect();
            assert_vec(
                &fit_values,
                &nums(&expected["fit"])?,
                RTOL_COEF,
                &format!("{path}.fit"),
            )?;
            assert_vec(
                &se_values,
                &nums(&expected["se_fit"])?,
                RTOL_VAR,
                &format!("{path}.se_fit"),
            )
        }
    }
}

/// `dsurvreg`/`psurvreg`/`qsurvreg` samples of the `distribution_functions`
/// case; `key` is `<dist>_scale<s>` or `t_df4_scale1`.
fn check_survreg_distribution(key: &str, expected: &Value) -> Result<(), String> {
    use crate::regression::survreg_distributions::{dsurvreg, psurvreg, qsurvreg};
    let (dist, parms) = if key.starts_with("t_df4") {
        ("t", Some(vec![4.0]))
    } else {
        (
            key.rsplit_once("_scale").map(|(d, _)| d).unwrap_or(key),
            None,
        )
    };
    let mean = nums(&expected["mean"])?;
    let scale = nums(&expected["scale"])?;
    let x = nums(&expected["x"])?;
    let p = nums(&expected["p"])?;
    let d = dsurvreg(x.clone(), mean.clone(), scale.clone(), dist, parms.clone())
        .map_err(|err| format!("dsurvreg: {err}"))?;
    assert_vec(&d, &nums(&expected["d"])?, RTOL_COEF, &format!("{key}.d"))?;
    let cdf = psurvreg(x, mean.clone(), scale.clone(), dist, parms.clone())
        .map_err(|err| format!("psurvreg: {err}"))?;
    assert_vec(
        &cdf,
        &nums(&expected["p_"])?,
        RTOL_COEF,
        &format!("{key}.p"),
    )?;
    let q = qsurvreg(p, mean, scale, dist, parms).map_err(|err| format!("qsurvreg: {err}"))?;
    assert_vec(&q, &nums(&expected["q"])?, RTOL_COEF, &format!("{key}.q"))
}

/// Every case of a `survreg`-shaped topic (`survreg`, `survreg-extra`).
fn check_survreg_topic(topic: &str) {
    use crate::regression::parametric_survival::{SurvregControl, SurvregData, survreg_fit};
    use crate::regression::survreg_distributions::SurvregDistribution;
    use crate::residuals::survreg_resid::SurvregResidType;

    let doc = load_topic(topic);
    let mut report = Report::new(topic);
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"];
        if name == "distribution_functions" {
            for (key, sample) in expected.as_object().expect("samples") {
                report.record(
                    name,
                    &format!("dist.{key}"),
                    check_survreg_distribution(key, sample),
                );
            }
            continue;
        }
        let args = &case["args"];
        let context = (|| -> Result<_, String> {
            let frame = case_frame(&doc, case)?;
            let formula = text(&case["formula"]).ok_or("no formula")?;
            let response = survreg_response(formula, &frame)?;
            // R's survreg fits an intercept (the kernel takes the design
            // matrix as given), so add the column of ones R would.
            let mut design = design(formula, &frame)?;
            if formula_has_intercept(formula) {
                design = design.with_intercept();
            }
            let weights = arg_nums(case, "weights");
            let rows: Vec<usize> = (0..response.time.len())
                .filter(|&i| {
                    response.time[i].is_finite()
                        && design.rows[i].iter().all(|v| v.is_finite())
                        && design.strata.as_ref().is_none_or(|s| s[i] >= 0)
                        && design.offset.as_ref().is_none_or(|o| o[i].is_finite())
                        && weights.as_ref().is_none_or(|w| w[i].is_finite())
                })
                .collect();
            let strata = design.strata.as_ref().map(|s| {
                pick(s, &rows)
                    .into_iter()
                    .map(|code| code as usize)
                    .collect::<Vec<usize>>()
            });
            let cluster = survreg_cluster_codes(formula, &frame)?.map(|codes| pick(&codes, &rows));
            let data = SurvregData::try_new(
                pick(&response.time, &rows),
                pick(&response.status, &rows),
                rows.iter().map(|&i| design.rows[i].clone()).collect(),
                response.time2.as_ref().map(|t| pick(t, &rows)),
                weights.as_ref().map(|w| pick(w, &rows)),
                design.offset.as_ref().map(|o| pick(o, &rows)),
                strata,
                cluster,
            )
            .map_err(|err| format!("SurvregData: {err}"))?;
            let parms = arg_nums(case, "parms");
            let distribution = SurvregDistribution::from_name(
                text(&args["dist"]).unwrap_or("weibull"),
                parms.as_deref(),
            )
            .map_err(|err| format!("distribution: {err}"))?;
            let init = arg_nums(case, "init");
            let scale = args["scale"].as_f64().unwrap_or(0.0);
            let mut control = SurvregControl::default();
            if let Some(iter_max) = args["control"]["iter.max"].as_u64() {
                control.iter_max = iter_max as usize;
            }
            let fit = survreg_fit(
                &data,
                &distribution,
                init.as_deref(),
                scale,
                &control,
                is_true(&args["robust"]),
            )
            .map_err(|err| format!("survreg: {err}"))?;
            let assign = design_assign(formula, &design.names);
            Ok((fit, frame, formula.to_string(), assign))
        })();
        let (fit, frame, formula, assign) = match context {
            Err(message) => {
                for aspect in ["coef", "scale", "loglik", "var", "linear_predictors"] {
                    report.record(name, aspect, Err(message.clone()));
                }
                continue;
            }
            Ok(context) => context,
        };
        let nvar = fit.nvar();
        // R's coef is the location part only ((Intercept), terms...); the
        // scale is reported separately.
        report.record(
            name,
            "coef",
            (|| {
                assert_vec(
                    &fit.coefficients[..nvar],
                    &named_values(&expected["coef"], &expected["coef_names"])?,
                    RTOL_COEF,
                    "coef",
                )
            })(),
        );
        report.record(
            name,
            "icoef",
            (|| assert_vec(&fit.icoef, &nums(&expected["icoef"])?, RTOL_COEF, "icoef"))(),
        );
        report.record(
            name,
            "scale",
            (|| assert_vec(&fit.scale, &nums(&expected["scale"])?, RTOL_COEF, "scale"))(),
        );
        report.record(
            name,
            "loglik",
            (|| {
                assert_vec(
                    &[fit.intercept_only_log_likelihood, fit.log_likelihood],
                    &nums(&expected["loglik"])?,
                    RTOL_COEF,
                    "loglik",
                )
            })(),
        );
        report.record(
            name,
            "var",
            (|| {
                // R's var is the full (coefficients, Log(scale) per stratum)
                // block; the kernel lays it out the same way.
                assert_matrix(
                    &fit.variance_matrix,
                    &matrix(&expected["var"])?,
                    RTOL_VAR,
                    "var",
                )
            })(),
        );
        if let Some(naive) = expected.get("naive_var") {
            report.record(
                name,
                "naive_var",
                (|| {
                    let actual = fit.naive_variance_matrix.as_deref().ok_or("no naive.var")?;
                    assert_matrix(actual, &matrix(naive)?, RTOL_VAR, "naive_var")
                })(),
            );
        }
        report.record(
            name,
            "iter",
            (|| assert_scalar(fit.iterations as f64, num(&expected["iter"])?, 0.0, "iter"))(),
        );
        report.record(
            name,
            "df",
            (|| assert_scalar(fit.df as f64, num(&expected["df"])?, 0.0, "df"))(),
        );
        report.record(
            name,
            "df_residual",
            (|| {
                assert_scalar(
                    fit.df_residual as f64,
                    num(&expected["df_residual"])?,
                    0.0,
                    "df_residual",
                )
            })(),
        );
        report.record(
            name,
            "linear_predictors",
            (|| {
                assert_vec(
                    &fit.linear_predictors,
                    &nums(&expected["linear_predictors"])?,
                    RTOL_COEF,
                    "linear_predictors",
                )
            })(),
        );
        report.record(
            name,
            "means",
            (|| assert_vec(&fit.means, &nums(&expected["means"])?, RTOL_COEF, "means"))(),
        );
        if let Some(parms) = expected.get("parms") {
            report.record(
                name,
                "parms",
                (|| assert_vec(&fit.distribution.parms, &nums(parms)?, RTOL_COEF, "parms"))(),
            );
        }
        if let Some(x) = expected.get("x") {
            report.record(
                name,
                "x",
                (|| assert_matrix(&fit.covariates, &matrix(&x["values"])?, RTOL_COEF, "x"))(),
            );
        }
        if let Some(residuals) = expected["residuals"].as_object() {
            for (kind, value) in residuals {
                if is_r_error(value) {
                    continue;
                }
                let aspect = format!("residuals.{kind}");
                report.record(
                    name,
                    &aspect,
                    (|| {
                        let residual_type =
                            SurvregResidType::parse(kind).map_err(|err| err.to_string())?;
                        let actual = fit
                            .residuals(residual_type, true, None, false)
                            .map_err(|err| format!("residuals: {err}"))?;
                        let result = if residual_type.is_matrix() {
                            assert_matrix(
                                &actual.values,
                                &matrix(&value["values"])?,
                                RTOL_COEF,
                                &aspect,
                            )
                        } else {
                            let values: Vec<f64> = actual.values.iter().map(|row| row[0]).collect();
                            assert_vec(&values, &nums(value)?, RTOL_COEF, &aspect)
                        };
                        // R's residuals.survreg gets the log(scale) derivatives
                        // of interval-censored rows wrong (see survreg_deriv);
                        // the crate follows survregc1.c instead.
                        result.map_err(|message| {
                            if fit.status.contains(&3) {
                                format!("R interval-row ds/dds/dsg bug: {message}")
                            } else {
                                message
                            }
                        })
                    })(),
                );
            }
        }
        if let Some(predictions) = expected["predict"].as_object() {
            for (kind, value) in predictions {
                if is_r_error(value) {
                    continue;
                }
                report.record(
                    name,
                    &format!("predict.{kind}"),
                    check_survreg_prediction(&fit, None, &assign, kind, value),
                );
            }
        }
        if let Some(predictions) = expected["predict_newdata"].as_object() {
            let newdata = (|| -> Result<_, String> {
                let new_frame = inline_frame(&expected["newdata"])?;
                let combined = append_rows(&frame, &new_frame)?;
                let mut design = design(&formula, &combined)?;
                if formula_has_intercept(&formula) {
                    design = design.with_intercept();
                }
                let n_new = new_frame.nrow();
                let rows = design.rows.split_off(design.rows.len() - n_new);
                let strata = design.strata.map(|s| {
                    s[s.len() - n_new..]
                        .iter()
                        .map(|&c| c as usize)
                        .collect::<Vec<_>>()
                });
                let offset = design.offset.map(|o| o[o.len() - n_new..].to_vec());
                Ok((rows, strata, offset))
            })();
            for (kind, value) in predictions {
                if is_r_error(value) {
                    continue;
                }
                report.record(
                    name,
                    &format!("predict_newdata.{kind}"),
                    newdata
                        .as_ref()
                        .map_err(Clone::clone)
                        .and_then(|(rows, strata, offset)| {
                            let newdata = SurvregNewdata {
                                covariates: rows,
                                offset: offset.as_deref(),
                                strata: strata.as_deref(),
                            };
                            // R's predict.survreg drops the offset of newdata;
                            // the crate applies it (see SurvregNewdata).
                            check_survreg_prediction(&fit, Some(&newdata), &assign, kind, value)
                                .map_err(|message| {
                                    if offset.is_some() {
                                        format!("R drops the newdata offset: {message}")
                                    } else {
                                        message
                                    }
                                })
                        }),
                );
            }
        }
    }
    report.finish();
}

#[test]
fn r_fixtures_survreg() {
    check_survreg_topic("survreg");
}

#[test]
fn r_fixtures_survreg_extra() {
    check_survreg_topic("survreg-extra");
}

// ---------------------------------------------------------------------------
// concordance (resid): R's concordance() through concordance::concordancefit
// ---------------------------------------------------------------------------

/// Integer codes of a column's levels (R's `as.integer(factor)`), 1-based.
fn level_codes(column: &Column) -> Vec<i32> {
    let levels = column.levels();
    (0..column.len())
        .map(|i| {
            column
                .label(i)
                .and_then(|label| levels.iter().position(|l| *l == label))
                .map_or(-1, |p| p as i32 + 1)
        })
        .collect()
}

struct ConcordanceCase {
    fit: crate::concordance::ConcordanceFit,
    x_names: Vec<String>,
}

fn concordance_fit_for_case(doc: &Value, case: &Value) -> Result<ConcordanceCase, String> {
    use crate::concordance::{ConcordanceOptions, TimeWeight, concordancefit};
    use crate::core::SurvResponse;
    let frame = case_frame(doc, case)?;
    let formula = text(&case["formula"]).ok_or("no formula")?;
    let args = &case["args"];
    for key in ["ymin", "ymax", "keepstrata", "timefix"] {
        if !args[key].is_null() {
            return unsupported(format!("harness: concordance argument {key}"));
        }
    }
    // A numeric response is `Surv(y)`: every observation is an event.
    let response = if formula.trim_start().starts_with("Surv(") {
        response(formula, &frame)?
    } else {
        let column = formula.split('~').next().ok_or("formula without ~")?.trim();
        let time = frame.get(column)?.numeric(column)?;
        let status = vec![1; time.len()];
        Response {
            start: None,
            time,
            status,
        }
    };
    let n = frame.nrow();
    let mut x_names = Vec::new();
    let mut columns: Vec<Vec<f64>> = Vec::new();
    let mut strata: Option<Vec<i32>> = None;
    let mut cluster: Option<Vec<i32>> = None;
    for term in rhs_terms(formula) {
        if let Some(inner) = term
            .strip_prefix("strata(")
            .and_then(|t| t.strip_suffix(')'))
        {
            strata = Some(level_codes(frame.get(inner)?));
        } else if let Some(inner) = term
            .strip_prefix("cluster(")
            .and_then(|t| t.strip_suffix(')'))
        {
            cluster = Some(level_codes(frame.get(inner)?));
        } else if let Some(inner) = term
            .strip_prefix("as.numeric(")
            .and_then(|t| t.strip_suffix(')'))
        {
            x_names.push(term.clone());
            columns.push(match frame.get(inner)? {
                Column::Num(values) => values.clone(),
                column => level_codes(column).iter().map(|&c| f64::from(c)).collect(),
            });
        } else if term.contains('(') {
            return unsupported(format!("harness: term {term}"));
        } else {
            x_names.push(term.clone());
            columns.push(frame.get(&term)?.numeric(&term)?);
        }
    }
    if let Some(name) = text(&args["cluster"]) {
        cluster = Some(level_codes(frame.get(name)?));
    }
    if columns.is_empty() {
        return unsupported("harness: no predictor");
    }
    let weights = arg_nums(case, "weights");
    let rows: Vec<usize> = (0..n)
        .filter(|&i| {
            response.time[i].is_finite()
                && response.start.as_ref().is_none_or(|s| s[i].is_finite())
                && columns.iter().all(|c| c[i].is_finite())
                && strata.as_ref().is_none_or(|s| s[i] > 0)
                && cluster.as_ref().is_none_or(|c| c[i] > 0)
                && weights.as_ref().is_none_or(|w| w[i].is_finite())
        })
        .collect();
    let x =
        ndarray::Array2::from_shape_fn((rows.len(), columns.len()), |(r, c)| columns[c][rows[r]]);
    let options = ConcordanceOptions {
        timewt: TimeWeight::parse(text(&args["timewt"]).unwrap_or("n"))
            .map_err(|err| err.to_string())?,
        influence: args["influence"].as_u64().unwrap_or(0) as u8,
        ranks: is_true(&args["ranks"]),
        reverse: is_true(&args["reverse"]),
        ..ConcordanceOptions::default()
    };
    let weights = weights.map(|w| pick(&w, &rows));
    let strata = strata.map(|s| pick(&s, &rows));
    let cluster = cluster.map(|c| pick(&c, &rows));
    let time = pick(&response.time, &rows);
    let status = pick(&response.status, &rows);
    let fit = match &response.start {
        Some(start) => {
            let data =
                crate::data_types::CountingProcessData::try_new(pick(start, &rows), time, status)
                    .map_err(|err| err.to_string())?;
            concordancefit(
                SurvResponse::Counting(&data),
                x.view(),
                weights.as_deref(),
                strata.as_deref(),
                cluster.as_deref(),
                &options,
            )
            .map_err(|err| format!("concordancefit: {err}"))?
        }
        None => {
            let data = crate::data_types::SurvivalData::try_new(time, status)
                .map_err(|err| err.to_string())?;
            concordancefit(
                SurvResponse::Right(&data),
                x.view(),
                weights.as_deref(),
                strata.as_deref(),
                cluster.as_deref(),
                &options,
            )
            .map_err(|err| format!("concordancefit: {err}"))?
        }
    };
    Ok(ConcordanceCase { fit, x_names })
}

fn check_concordance_aspect(
    case: &ConcordanceCase,
    expected: &Value,
    aspect: &str,
) -> Result<(), String> {
    let fit = &case.fit;
    match aspect {
        "concordance" => assert_vec(
            &fit.concordance,
            &nums(&expected["concordance"])?,
            RTOL_COEF,
            "concordance",
        ),
        "n" => {
            let expected = nums(&expected["n"])?[0] as usize;
            if fit.n == expected {
                Ok(())
            } else {
                Err(format!("n: {} != {expected}", fit.n))
            }
        }
        "count" => {
            // A named vector for one predictor without kept strata, else a
            // matrix with one row per predictor (R's column names) or per
            // stratum (`sex=1`, ...); both orders match `fit.count`.
            let count = &expected["count"];
            let names =
                serde_json::json!(["concordant", "discordant", "tied.x", "tied.y", "tied.xy"]);
            let expected_rows: Vec<Vec<f64>> = if count["values"].is_array() {
                let row_names: Vec<&str> = names_of(&count["rownames"]);
                if fit.count_strata.is_none()
                    && row_names
                        .iter()
                        .any(|name| !case.x_names.iter().any(|x| x == name))
                {
                    return Err(format!("count rows {row_names:?} are not the predictors"));
                }
                matrix(&count["values"])?
            } else {
                vec![named_values(count, &names)?]
            };
            let actual_rows: Vec<Vec<f64>> = fit
                .count
                .iter()
                .map(|c| vec![c.concordant, c.discordant, c.tied_x, c.tied_y, c.tied_xy])
                .collect();
            if actual_rows.len() != expected_rows.len() {
                return Err(format!(
                    "count has {} rows, expected {}",
                    actual_rows.len(),
                    expected_rows.len()
                ));
            }
            for (row, (actual, expected)) in actual_rows.iter().zip(&expected_rows).enumerate() {
                assert_vec(actual, expected, 1e-12, &format!("count[{row}]"))?;
            }
            Ok(())
        }
        "var" => {
            let var = fit.var.as_ref().ok_or("var is None")?;
            if expected["var"][0].is_array() {
                assert_matrix(var, &matrix(&expected["var"])?, RTOL_VAR, "var")
            } else {
                assert_vec(&[var[0][0]], &nums(&expected["var"])?, RTOL_VAR, "var")
            }
        }
        "cvar" => assert_vec(
            fit.cvar.as_ref().ok_or("cvar is None")?,
            &nums(&expected["cvar"])?,
            RTOL_VAR,
            "cvar",
        ),
        "dfbeta" => {
            let dfbeta = fit.dfbeta.as_ref().ok_or("dfbeta is None")?;
            if expected["dfbeta"][0].is_array() {
                assert_matrix(dfbeta, &matrix(&expected["dfbeta"])?, RTOL_VAR, "dfbeta")
            } else {
                let column: Vec<f64> = dfbeta.iter().map(|row| row[0]).collect();
                assert_vec(&column, &nums(&expected["dfbeta"])?, RTOL_VAR, "dfbeta")
            }
        }
        "influence" => {
            let influence = fit.influence.as_ref().ok_or("influence is None")?;
            assert_matrix(
                &influence[0],
                &matrix(&expected["influence"])?,
                RTOL_VAR,
                "influence",
            )
        }
        other => unsupported(format!("harness: concordance aspect {other}")),
    }
}

