/// Aspects of a survcheck case.
const SURVCHECK_ASPECTS: &[&str] = &[
    "states",
    "transitions",
    "events",
    "flag",
    "istate",
    "n",
    "problems",
];

/// Build the multi-state response of a survcheck/brier case: event codes
/// into the factor levels of the status column (level 0 = censored), the
/// state names, and the optional istate column as codes into its levels.
struct MultiStateResponse {
    start: Option<Vec<f64>>,
    stop: Vec<f64>,
    status: Vec<i32>,
    states: Vec<String>,
}

fn multistate_response(formula: &str, frame: &Frame) -> Result<MultiStateResponse, String> {
    let lhs = formula.split('~').next().ok_or("formula without ~")?.trim();
    let inner = lhs
        .strip_prefix("Surv(")
        .and_then(|rest| rest.strip_suffix(')'))
        .ok_or_else(|| format!("unsupported: harness: response {lhs:?}"))?;
    let args: Vec<&str> = inner.split(',').map(str::trim).collect();
    let status_name = *args.last().ok_or("empty Surv()")?;
    let column = frame.get(status_name)?;
    let (status, states) = match column {
        Column::Str(values, levels) => {
            let levels = if levels.is_empty() {
                column.levels()
            } else {
                levels.clone()
            };
            let status = values
                .iter()
                .map(|value| {
                    value
                        .as_ref()
                        .and_then(|v| levels.iter().position(|l| l == v))
                        .map_or(0, |p| p as i32)
                })
                .collect();
            (status, levels[1..].to_vec())
        }
        Column::Num(_) => (
            status_column(status_name, frame)?,
            vec!["event".to_string()],
        ),
    };
    let (start, stop) = match args.len() {
        2 => (None, frame.get(args[0])?.numeric(args[0])?),
        3 => (
            Some(frame.get(args[0])?.numeric(args[0])?),
            frame.get(args[1])?.numeric(args[1])?,
        ),
        _ => return unsupported("harness: Surv() arity"),
    };
    Ok(MultiStateResponse {
        start,
        stop,
        status,
        states,
    })
}

/// Codes (1-based) and levels of a factor/character column.
fn factor_codes(column: &Column) -> (Vec<i32>, Vec<String>) {
    let levels = column.levels();
    let codes = (0..column.len())
        .map(|i| {
            column
                .label(i)
                .and_then(|label| levels.iter().position(|l| *l == label))
                .map_or(0, |p| p as i32 + 1)
        })
        .collect();
    (codes, levels)
}

fn named_matrix_rows(value: &Value) -> Vec<String> {
    names_of(&value["rownames"])
        .into_iter()
        .map(str::to_string)
        .collect()
}

fn named_matrix_cols(value: &Value) -> Vec<String> {
    names_of(&value["colnames"])
        .into_iter()
        .map(str::to_string)
        .collect()
}

fn check_survcheck_case(doc: &Value, case: &Value, report: &mut Report) {
    use crate::validation::{SurvCheckInput, SurvCheckIstate, SurvCheckProblem, survcheck};
    let name = text(&case["name"]).expect("case name");
    let expected = &case["expected"];
    let prepared = (|| -> Result<_, String> {
        let frame = case_frame(doc, case)?;
        let formula = text(&case["formula"]).ok_or("no formula")?;
        let response = multistate_response(formula, &frame)?;
        let id_name = text(&case["args"]["id"]).ok_or("no id")?;
        let id: Vec<i64> = frame
            .get(id_name)?
            .numeric(id_name)?
            .into_iter()
            .map(|v| v as i64)
            .collect();
        let istate = match text(&case["args"]["istate"]) {
            Some(column) => Some(factor_codes(frame.get(column)?)),
            None => None,
        };
        // Surv() drops rows with start >= stop (NA created); survcheck
        // then renumbers the problem rows back to the original data.
        let rows: Vec<usize> = (0..response.stop.len())
            .filter(|&i| {
                response
                    .start
                    .as_ref()
                    .is_none_or(|start| start[i] < response.stop[i])
            })
            .collect();
        let start = response.start.as_ref().map(|s| pick(s, &rows));
        let stop = pick(&response.stop, &rows);
        let status = pick(&response.status, &rows);
        let id = pick(&id, &rows);
        let istate_codes = istate.as_ref().map(|(codes, _)| pick(codes, &rows));
        let istate = match (&istate_codes, &istate) {
            (Some(codes), Some((_, levels))) => Some(SurvCheckIstate { codes, levels }),
            _ => None,
        };
        let result = survcheck(&SurvCheckInput {
            id: &id,
            time1: start.as_deref(),
            time2: &stop,
            status: &status,
            states: &response.states,
            istate,
            istate0: "(s0)",
            censor_label: "censored",
            timefix: true,
        })
        .map_err(|err| format!("survcheck: {err}"))?;
        Ok((result, rows))
    })();
    match prepared {
        Err(message) => {
            for aspect in SURVCHECK_ASPECTS {
                report.record(name, aspect, Err(message.clone()));
            }
        }
        Ok((result, rows)) => {
            let check = |aspect: &str| -> Result<(), String> {
                match aspect {
                    "states" => {
                        let expected = names_of(&expected["states"]);
                        if result
                            .states
                            .iter()
                            .map(String::as_str)
                            .ne(expected.iter().copied())
                        {
                            return Err(format!("states {:?} != {:?}", result.states, expected));
                        }
                        Ok(())
                    }
                    "transitions" => {
                        let table = &expected["transitions"];
                        if result.transitions.from_states != named_matrix_rows(table)
                            || result.transitions.to_states != named_matrix_cols(table)
                        {
                            return Err(format!(
                                "transitions dimnames ({:?} x {:?}) != ({:?} x {:?})",
                                result.transitions.from_states,
                                result.transitions.to_states,
                                named_matrix_rows(table),
                                named_matrix_cols(table)
                            ));
                        }
                        let actual: Vec<Vec<f64>> = result
                            .transitions
                            .counts
                            .iter()
                            .map(|row| row.iter().map(|&c| c as f64).collect())
                            .collect();
                        assert_matrix(&actual, &matrix(&table["values"])?, 0.0, "transitions")
                    }
                    "events" => {
                        let table = &expected["events"];
                        let Some(events) = &result.events else {
                            return if table.is_null() {
                                Ok(())
                            } else {
                                Err("no events table".to_string())
                            };
                        };
                        let expected_cols: Vec<String> =
                            events.count.iter().map(|c| c.to_string()).collect();
                        if events.states != named_matrix_rows(table)
                            || expected_cols != named_matrix_cols(table)
                        {
                            return Err(format!(
                                "events dimnames ({:?} x {:?}) != ({:?} x {:?})",
                                events.states,
                                expected_cols,
                                named_matrix_rows(table),
                                named_matrix_cols(table)
                            ));
                        }
                        let actual: Vec<Vec<f64>> = events
                            .subjects
                            .iter()
                            .map(|row| row.iter().map(|&c| c as f64).collect())
                            .collect();
                        assert_matrix(&actual, &matrix(&table["values"])?, 0.0, "events")
                    }
                    "flag" => {
                        let flag = &expected["flag"];
                        let actual = [
                            result.flag.overlap,
                            result.flag.gap,
                            result.flag.jump,
                            result.flag.teleport,
                            result.flag.duplicate,
                        ];
                        for (value, key) in
                            actual
                                .iter()
                                .zip(["overlap", "gap", "jump", "teleport", "duplicate"])
                        {
                            assert_scalar(
                                *value as f64,
                                num(&flag[key])?,
                                0.0,
                                &format!("flag.{key}"),
                            )?;
                        }
                        Ok(())
                    }
                    "istate" => {
                        let expected = names_of(&expected["istate"]);
                        if result
                            .istate
                            .iter()
                            .map(String::as_str)
                            .ne(expected.iter().copied())
                        {
                            return Err(format!(
                                "istate {:?} != {:?}",
                                &result.istate[..8.min(result.istate.len())],
                                &expected[..8.min(expected.len())]
                            ));
                        }
                        Ok(())
                    }
                    "n" => {
                        let n = &expected["n"];
                        assert_scalar(result.n_id as f64, num(&n["id"])?, 0.0, "n.id")?;
                        assert_scalar(
                            result.n_observations as f64,
                            num(&n["observations"])?,
                            0.0,
                            "n.observations",
                        )?;
                        assert_scalar(
                            result.n_transitions as f64,
                            num(&n["transitions"])?,
                            0.0,
                            "n.transitions",
                        )
                    }
                    "problems" => {
                        for (key, actual) in [
                            ("overlap", &result.overlap),
                            ("gap", &result.gap),
                            ("teleport", &result.teleport),
                            ("jump", &result.jump),
                        ] {
                            let expected = &expected[key];
                            match (actual, expected.is_null()) {
                                (None, true) => {}
                                (None, false) => {
                                    return Err(format!("{key}: expected problems"));
                                }
                                (Some(_), true) => {
                                    return Err(format!("{key}: unexpected problems"));
                                }
                                (Some(SurvCheckProblem { row, id }), false) => {
                                    // R reports 1-based rows of the original data
                                    let actual_rows: Vec<f64> =
                                        row.iter().map(|&r| rows[r] as f64 + 1.0).collect();
                                    assert_vec(
                                        &actual_rows,
                                        &nums(&expected["row"])?,
                                        0.0,
                                        &format!("{key}.row"),
                                    )?;
                                    let actual_ids: Vec<f64> =
                                        id.iter().map(|&i| i as f64).collect();
                                    assert_vec(
                                        &actual_ids,
                                        &nums(&expected["id"])?,
                                        0.0,
                                        &format!("{key}.id"),
                                    )?;
                                }
                            }
                        }
                        Ok(())
                    }
                    other => unsupported(format!("aspect {other}")),
                }
            };
            for aspect in SURVCHECK_ASPECTS {
                report.record(name, aspect, check(aspect));
            }
        }
    }
}

