/// The expanded survobrien frame as a [`Frame`], with the R column names.
fn survobrien_frame(case: &Value, frame: &Frame) -> Result<(Frame, Vec<String>), String> {
    use crate::validation::{SurvObrienInput, survobrien};
    let formula = text(&case["formula"]).ok_or("no formula")?;
    let response = response(formula, frame)?;
    let mut keepers: Vec<(String, &Column)> = Vec::new();
    let mut continuous_names = Vec::new();
    let mut continuous = Vec::new();
    for term in rhs_terms(formula) {
        if term.starts_with("strata(") || term.starts_with("cluster(") {
            return unsupported("harness: survobrien strata/cluster terms");
        }
        if let Some(inner) = term
            .strip_prefix("factor(")
            .and_then(|t| t.strip_suffix(')'))
        {
            keepers.push((inner.to_string(), frame.get(inner)?));
            continue;
        }
        match frame.get(&term)? {
            Column::Num(values) => {
                continuous_names.push(term.clone());
                continuous.push(values.clone());
            }
            column @ Column::Str(..) => keepers.push((term.clone(), column)),
        }
    }
    let rows = complete_rows(
        &response,
        &Design {
            names: continuous_names.clone(),
            rows: (0..frame.nrow())
                .map(|i| continuous.iter().map(|c| c[i]).collect())
                .collect(),
            strata: None,
            offset: None,
        },
        &[],
    );
    let continuous: Vec<Vec<f64>> = continuous.iter().map(|c| pick(c, &rows)).collect();
    let time = pick(&response.time, &rows);
    let status = pick(&response.status, &rows);
    let start = response.start.as_ref().map(|s| pick(s, &rows));
    let expansion = survobrien(&SurvObrienInput {
        start: start.as_deref(),
        time: &time,
        status: &status,
        strata: None,
        continuous: &continuous,
    })
    .map_err(|err| format!("survobrien: {err}"))?;
    let original_rows: Vec<usize> = expansion.row.iter().map(|&r| rows[r]).collect();
    let mut columns: Vec<(String, Column)> = Vec::new();
    if let Some(start) = &expansion.start {
        columns.push(("start".to_string(), Column::Num(start.clone())));
        columns.push(("stop".to_string(), Column::Num(expansion.time.clone())));
    } else {
        columns.push(("time".to_string(), Column::Num(expansion.time.clone())));
    }
    columns.push((
        "status".to_string(),
        Column::Num(expansion.status.iter().map(|&s| f64::from(s)).collect()),
    ));
    for (name, column) in &keepers {
        columns.push((name.clone(), column.subset(&original_rows)));
    }
    columns.push((
        ".id.".to_string(),
        Column::Num(expansion.row.iter().map(|&r| r as f64 + 1.0).collect()),
    ));
    for (name, values) in continuous_names.iter().zip(&expansion.transformed) {
        columns.push((name.clone(), Column::Num(values.clone())));
    }
    columns.push((
        ".strata.".to_string(),
        Column::Num(expansion.strata.iter().map(|&s| s as f64).collect()),
    ));
    Ok((Frame { columns }, continuous_names))
}

fn check_survobrien_case(doc: &Value, case: &Value, report: &mut Report) {
    let name = text(&case["name"]).expect("case name");
    let expected = &case["expected"];
    let prepared = (|| -> Result<_, String> {
        let frame = case_frame(doc, case)?;
        survobrien_frame(case, &frame)
    })();
    let (frame_result, coef_result) = match prepared {
        Err(message) => (Err(message.clone()), Err(message)),
        Ok((expanded, _)) => {
            let frame_result = (|| -> Result<(), String> {
                let r_frame = expected["frame"]["columns"]
                    .as_object()
                    .ok_or("no frame columns")?;
                for (column, values) in r_frame {
                    let Value::Array(items) = values else {
                        continue;
                    };
                    if items.first().is_some_and(Value::is_string) {
                        continue;
                    }
                    let actual = expanded.get(column)?.numeric(column)?;
                    assert_vec(
                        &actual,
                        &nums(values)?,
                        RTOL_COEF,
                        &format!("frame.{column}"),
                    )?;
                }
                Ok(())
            })();
            let coef_result = (|| -> Result<(), String> {
                let cox_formula = text(&expected["cox_formula"]).ok_or("no cox formula")?;
                let response = response(cox_formula, &expanded)?;
                let design = design(cox_formula, &expanded)?;
                let fit = efron_cox_fit(
                    &response,
                    &design,
                    None,
                    &(0..expanded.nrow()).collect::<Vec<_>>(),
                )?;
                let expected_coef: Vec<f64> = design
                    .names
                    .iter()
                    .map(|name| num(&expected["coxph_coef"][name]))
                    .collect::<Result<_, _>>()?;
                assert_vec(&fit.coefficients, &expected_coef, RTOL_COEF, "coef")
            })();
            (frame_result, coef_result)
        }
    };
    report.record(name, "frame", frame_result);
    report.record(name, "coxph_coef", coef_result);
}

