/// Model matrices, one per level of the term of interest, and the levels.
type YatesMatrices = (Vec<Vec<Vec<f64>>>, Vec<String>);

/// The per-level model matrices of a yates term over a population.
fn yates_xmatlist(
    frame: &Frame,
    design: &Design,
    formula: &str,
    term: &str,
    population: &str,
) -> Result<YatesMatrices, String> {
    let term_column = term
        .strip_prefix("factor(")
        .and_then(|t| t.strip_suffix(')'))
        .unwrap_or(term);
    let column = frame.get(term_column)?;
    if matches!(column, Column::Num(_)) && !term.starts_with("factor(") {
        return unsupported("yates on a continuous term");
    }
    let levels = column.levels();
    let term_cols: Vec<usize> = design
        .names
        .iter()
        .enumerate()
        .filter(|(_, name)| name.starts_with(term))
        .map(|(i, _)| i)
        .collect();
    if term_cols.len() != levels.len() - 1 {
        return Err(format!(
            "term {term}: {} design columns for {} levels",
            term_cols.len(),
            levels.len()
        ));
    }
    // The population rows over the other terms.
    let other_terms: Vec<String> = rhs_terms(formula)
        .into_iter()
        .filter(|t| t != term && t != "1")
        .collect();
    let categorical: Vec<(String, Vec<usize>, Vec<String>)> = other_terms
        .iter()
        .filter_map(|t| {
            let column_name = t
                .strip_prefix("factor(")
                .and_then(|x| x.strip_suffix(')'))
                .unwrap_or(t);
            let column = frame.get(column_name).ok()?;
            let is_factor = t.starts_with("factor(") || matches!(column, Column::Str(..));
            if !is_factor {
                return None;
            }
            let levels = column.levels();
            let cols: Vec<usize> = design
                .names
                .iter()
                .enumerate()
                .filter(|(_, name)| name.starts_with(t.as_str()))
                .map(|(i, _)| i)
                .collect();
            Some((t.clone(), cols, levels))
        })
        .collect();
    let all_categorical = categorical.len() == other_terms.len();
    let population_rows: Vec<Vec<f64>> = match population {
        "data" => design.rows.clone(),
        "factorial" | "sas" => {
            if population == "factorial" && !all_categorical {
                return unsupported("population=factorial with continuous adjusters");
            }
            // every combination of the categorical adjusters' levels
            let mut combos: Vec<Vec<f64>> = vec![vec![0.0; design.names.len()]];
            for (_, cols, levels) in &categorical {
                let mut next = Vec::new();
                for base in &combos {
                    for level in 0..levels.len() {
                        let mut row = base.clone();
                        for (k, &col) in cols.iter().enumerate() {
                            row[col] = f64::from(level == k + 1);
                        }
                        next.push(row);
                    }
                }
                combos = next;
            }
            if all_categorical {
                combos
            } else {
                // sas: factorial for the categoricals crossed with the data
                // rows of the continuous adjusters
                let categorical_cols: Vec<usize> = categorical
                    .iter()
                    .flat_map(|(_, cols, _)| cols.clone())
                    .collect();
                let mut rows = Vec::new();
                for combo in &combos {
                    for data_row in &design.rows {
                        let mut row = data_row.clone();
                        for &col in &categorical_cols {
                            row[col] = combo[col];
                        }
                        rows.push(row);
                    }
                }
                rows
            }
        }
        other => return unsupported(format!("population {other}")),
    };
    let xmatlist = (0..levels.len())
        .map(|level| {
            population_rows
                .iter()
                .map(|row| {
                    let mut row = row.clone();
                    for (k, &col) in term_cols.iter().enumerate() {
                        row[col] = f64::from(level == k + 1);
                    }
                    row
                })
                .collect()
        })
        .collect();
    Ok((xmatlist, levels))
}

fn check_yates_case(doc: &Value, case: &Value, report: &mut Report) {
    use crate::validation::{YatesInput, YatesTest, population_means, yates};
    let aspects = ["estimate", "test", "mvar", "cmat"];
    let name = text(&case["name"]).expect("case name");
    let expected = &case["expected"];
    let prepared = (|| -> Result<_, String> {
        if text(&case["fit"]) != Some("coxph") {
            return unsupported(format!(
                "yates on a {} fit",
                text(&case["fit"]).unwrap_or("?")
            ));
        }
        let args = &case["args"];
        if !args["predict"].is_null() {
            return unsupported("yates predict != linear");
        }
        let population = text(&args["population"]).unwrap_or("data");
        let test = YatesTest::parse(text(&args["test"]).unwrap_or("global"))
            .map_err(|err| err.to_string())?;
        let term = text(&args["term"]).ok_or("no term")?;
        let cox = cox_fit_for_case(doc, case)?;
        let frame = case_frame(doc, case)?;
        let formula = text(&case["formula"]).ok_or("no formula")?;
        let full_design = design(formula, &frame)?;
        let response = response(formula, &frame)?;
        let rows = complete_rows(&response, &full_design, &[]);
        let design = Design {
            names: full_design.names.clone(),
            rows: rows.iter().map(|&i| full_design.rows[i].clone()).collect(),
            strata: None,
            offset: None,
        };
        let frame = frame.subset(&rows);
        let (xmatlist, _) = yates_xmatlist(&frame, &design, formula, term, population)?;
        let cmat = population_means(&xmatlist, None).map_err(|err| err.to_string())?;
        let beta = cox.fit.coefficients.clone();
        let offset = -cox
            .fit
            .means
            .iter()
            .zip(&beta)
            .map(|(m, b)| m * b)
            .sum::<f64>();
        let vmat = matrix_rows(&cox.fit.var);
        let result = yates(&YatesInput {
            cmat: &cmat,
            beta: &beta,
            vmat: &vmat,
            offset,
            sigma2: None,
            estimable: None,
            test,
        })
        .map_err(|err| err.to_string())?;
        Ok(result)
    })();
    match prepared {
        Err(message) => {
            for aspect in aspects {
                report.record(name, aspect, Err(message.clone()));
            }
        }
        Ok(result) => {
            let check = |aspect: &str| -> Result<(), String> {
                match aspect {
                    "estimate" => {
                        let columns = &expected["estimate"]["columns"];
                        let pmm: Vec<f64> = result.estimate.iter().map(|e| e.pmm).collect();
                        let std: Vec<f64> = result.estimate.iter().map(|e| e.std).collect();
                        assert_vec(&pmm, &nums(&columns["pmm"])?, RTOL_COEF, "pmm")?;
                        assert_vec(&std, &nums(&columns["std"])?, RTOL_VAR, "std")
                    }
                    "test" => {
                        let table = matrix(&expected["test"]["values"])?;
                        let actual: Vec<Vec<f64>> = result
                            .test
                            .iter()
                            .map(|t| vec![t.chisq, t.df as f64])
                            .collect();
                        assert_matrix(&actual, &table, RTOL_VAR, "test")
                    }
                    "mvar" => {
                        assert_matrix(&result.mvar, &matrix(&expected["mvar"])?, RTOL_VAR, "mvar")
                    }
                    "cmat" => assert_matrix(
                        &result.cmat,
                        &matrix(&expected["cmat"]["values"])?,
                        RTOL_COEF,
                        "cmat",
                    ),
                    other => unsupported(format!("aspect {other}")),
                }
            };
            for aspect in aspects {
                report.record(name, aspect, check(aspect));
            }
        }
    }
}

