/// `survfit(fit)` for an Efron Cox fit (`agsurv` with `survtype = 3`):
/// the baseline cumulative hazard at the distinct times.
fn efron_baseline(fit: &CoxPHFit) -> (Vec<f64>, Vec<f64>) {
    let n = fit.time.len();
    let risk: Vec<f64> = fit.linear_predictors.iter().map(|lp| lp.exp()).collect();
    let mut times: Vec<f64> = fit.time.clone();
    times.sort_by(f64::total_cmp);
    times.dedup();
    let mut cumhaz = Vec::with_capacity(times.len());
    let mut total = 0.0;
    for &t in &times {
        let mut nrisk = 0.0;
        let mut erisk = 0.0;
        let mut deaths = 0usize;
        for i in 0..n {
            let at_risk = fit.time[i] >= t && fit.entry.as_ref().is_none_or(|e| e[i] < t);
            if at_risk {
                nrisk += fit.weights[i] * risk[i];
            }
            if fit.time[i] == t && fit.status[i] == 1 {
                erisk += fit.weights[i] * risk[i];
                deaths += 1;
            }
        }
        if deaths > 0 {
            let d = deaths as f64;
            let nevent: f64 = (0..n)
                .filter(|&i| fit.time[i] == t && fit.status[i] == 1)
                .map(|i| fit.weights[i])
                .sum();
            let sum1: f64 = (0..deaths)
                .map(|j| 1.0 / (nrisk - erisk * j as f64 / d) / d)
                .sum();
            total += nevent * sum1;
        }
        cumhaz.push(total);
    }
    (times, cumhaz)
}

#[test]
fn r_fixtures_royston_brier() {
    use crate::validation::brier::{BrierInput, brier};
    use crate::validation::{RoystonInput, royston};
    let doc = load_topic("royston_brier");
    let mut report = Report::new("royston_brier");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = case["expected"].as_object().expect("expected");
        let cox = cox_fit_for_case(&doc, &{
            let mut case = case.clone();
            case["args"] = serde_json::json!({});
            case
        });
        for (aspect, value) in expected {
            let result = (|| -> Result<(), String> {
                let cox = cox.as_ref().map_err(Clone::clone)?;
                let fit = &cox.fit;
                if aspect.starts_with("royston") {
                    let n_event = fit.status.iter().filter(|&&s| s == 1).count();
                    let result = royston(&RoystonInput {
                        eta: &fit.linear_predictors,
                        time: &fit.time,
                        status: &fit.status,
                        entry_times: fit.entry.as_deref(),
                        loglik: fit.loglik,
                        n_event,
                        n_coef: fit.coefficients.len(),
                        ties: true,
                        adjust: aspect.ends_with("adjust"),
                    })
                    .map_err(|err| err.to_string())?;
                    for (key, actual) in [
                        ("D", result.d),
                        ("se(D)", result.se_d),
                        ("R.D", result.r_d),
                        ("R.KO", result.r_ko),
                        ("R.N", result.r_n),
                        ("C.GH", result.c_gh),
                    ] {
                        assert_scalar(actual, num(&value[key])?, RTOL_VAR, key)?;
                    }
                    Ok(())
                } else {
                    let times = nums(&value["times"])?;
                    let (base_time, base_cumhaz) = efron_baseline(fit);
                    let phat: Vec<Vec<f64>> = times
                        .iter()
                        .map(|&t| {
                            let k = base_time.partition_point(|&u| u <= t);
                            let h0 = if k == 0 { 0.0 } else { base_cumhaz[k - 1] };
                            fit.linear_predictors
                                .iter()
                                .map(|lp| 1.0 - (-h0 * lp.exp()).exp())
                                .collect()
                        })
                        .collect();
                    let result = brier(&BrierInput {
                        time: &fit.time,
                        status: &fit.status,
                        weights: None,
                        times: &times,
                        phat: &phat,
                        ties: aspect != "brier_ties_false",
                        efron: false,
                        timefix: true,
                    })
                    .map_err(|err| err.to_string())?;
                    assert_vec(&result.brier, &nums(&value["brier"])?, RTOL_VAR, "brier")?;
                    assert_vec(
                        &result.rsquared,
                        &nums(&value["rsquared"])?,
                        RTOL_VAR,
                        "rsquared",
                    )
                }
            })();
            report.record(name, aspect, result);
        }
    }
    report.finish();
}

