/// The Kaplan-Meier fit of a survfit case, split into its curves, and the
/// number of observations of each (`validation::survmean` takes the
/// curves of one `survfit` object).
fn km_curves_for_case(doc: &Value, case: &Value) -> Result<(SurvfitKMResult, Vec<f64>), String> {
    let KMCase { data, options } = km_case(doc, case)?;
    let fit = survfitkm(&data, &options).map_err(|err| format!("survfitkm: {err}"))?;
    let n: Vec<f64> = fit.n.iter().map(|&count| count as f64).collect();
    Ok((fit, n))
}

/// Every curve of a fit as a [`crate::validation::SurvfitCurve`].
fn validation_curves(fit: &SurvfitKMResult) -> Vec<crate::validation::SurvfitCurve<'_>> {
    fit.curve_ranges()
        .into_iter()
        .map(|range| crate::validation::SurvfitCurve::from_km_curve(fit, range))
        .collect()
}

/// Compare `survmean` rows with a `summary(fit)$table` (a named matrix for
/// several curves, a named vector for one).
fn check_summary_table(
    rows: &[crate::validation::SurvfitSummaryRow],
    table: &Value,
) -> Result<(), String> {
    let (colnames, values): (Vec<String>, Vec<Vec<f64>>) = if table.get("values").is_some() {
        (named_matrix_cols(table), matrix(&table["values"])?)
    } else {
        let map = table.as_object().ok_or("summary table")?;
        let names: Vec<String> = map.keys().cloned().collect();
        let values = names
            .iter()
            .map(|k| num(&map[k]))
            .collect::<Result<Vec<_>, _>>()?;
        (names, vec![values])
    };
    if rows.len() != values.len() {
        return Err(format!("{} rows, expected {}", rows.len(), values.len()));
    }
    for (row, expected_row) in rows.iter().zip(&values) {
        for (column, expected_value) in colnames.iter().zip(expected_row) {
            let actual = match column.as_str() {
                "records" => row.records,
                "n.max" | "n.id" => row.n_max,
                "n.start" => row.n_start,
                "events" => row.events,
                "rmean" => row.rmean.ok_or("no rmean")?,
                "se(rmean)" => row.se_rmean.ok_or("no se(rmean)")?,
                "median" => row.median,
                c if c.ends_with("LCL") => row.lower.ok_or("no LCL")?,
                c if c.ends_with("UCL") => row.upper.ok_or("no UCL")?,
                other => return Err(format!("unknown column {other}")),
            };
            let rtol = if matches!(
                column.as_str(),
                "records" | "n.max" | "n.id" | "n.start" | "events"
            ) {
                0.0
            } else {
                RTOL_VAR
            };
            assert_scalar(actual, *expected_value, rtol, column)?;
        }
        if colnames.iter().all(|c| c != "rmean") && row.rmean.is_some() {
            return Err("unexpected rmean column".to_string());
        }
    }
    Ok(())
}

/// Compare `quantile_survfit` with a `quantile(fit, conf.int = TRUE)` object.
fn check_quantiles(
    result: &crate::validation::SurvfitCurveQuantiles,
    table: &Value,
) -> Result<(), String> {
    let as_matrix = |value: &Value| -> Result<Vec<Vec<f64>>, String> {
        if value
            .as_array()
            .is_some_and(|rows| rows.first().is_some_and(Value::is_array))
        {
            matrix(value)
        } else {
            Ok(vec![nums(value)?])
        }
    };
    assert_matrix(
        &result.quantile,
        &as_matrix(&table["quantile"])?,
        RTOL_VAR,
        "quantile",
    )?;
    let lower = result.lower.as_ref().ok_or("no lower")?;
    let upper = result.upper.as_ref().ok_or("no upper")?;
    assert_matrix(lower, &as_matrix(&table["lower"])?, RTOL_VAR, "lower")?;
    assert_matrix(upper, &as_matrix(&table["upper"])?, RTOL_VAR, "upper")
}

/// The extra validation cases generated under the `validation-extra` topic.
#[test]
fn r_fixtures_validation_extra() {
    use crate::validation::{AnovaKind, RmeanOption, anova_coxph, quantile_survfit, survmean};
    let doc = load_topic("validation-extra");
    let mut report = Report::new("validation-extra");
    for case in doc["cases"].as_array().expect("cases") {
        let name = text(&case["name"]).expect("case name");
        let expected = &case["expected"];
        if name.starts_with("survobrien_") {
            check_survobrien_case(&doc, case, &mut report);
        } else if name.starts_with("yates_") {
            check_yates_case(&doc, case, &mut report);
        } else if name.starts_with("survcheck_") {
            check_survcheck_case(&doc, case, &mut report);
        } else if name.starts_with("turnbull_") {
            check_turnbull_case(&doc, case, &mut report);
        } else if name.starts_with("anova_") {
            let result = (|| -> Result<(), String> {
                let frame = case_frame(&doc, case)?;
                let formulas = names_of(&case["formulas"]);
                let mut loglik = Vec::new();
                let mut df = Vec::new();
                for formula in &formulas {
                    let response = response(formula, &frame)?;
                    let design = design(formula, &frame)?;
                    let rows = complete_rows(&response, &design, &[]);
                    let fit = efron_cox_fit(&response, &design, None, &rows)?;
                    loglik.push(fit.loglik[1]);
                    df.push(design.names.len());
                }
                let names: Vec<String> = (1..=formulas.len()).map(|i| i.to_string()).collect();
                let table = anova_coxph(&loglik, &df, &names, AnovaKind::Models, true)
                    .map_err(|err| err.to_string())?;
                let actual_loglik: Vec<f64> = table.rows.iter().map(|r| r.loglik).collect();
                assert_vec(
                    &actual_loglik,
                    &nums(&expected["loglik"])?,
                    RTOL_COEF,
                    "loglik",
                )?;
                let actual_chisq: Vec<f64> = table
                    .rows
                    .iter()
                    .map(|r| r.chisq.unwrap_or(f64::NAN))
                    .collect();
                assert_vec(&actual_chisq, &nums(&expected["chisq"])?, RTOL_VAR, "chisq")?;
                let actual_df: Vec<f64> = table
                    .rows
                    .iter()
                    .map(|r| r.df.map_or(f64::NAN, |d| d as f64))
                    .collect();
                assert_vec(&actual_df, &nums(&expected["df"])?, 0.0, "df")?;
                let actual_p: Vec<f64> = table
                    .rows
                    .iter()
                    .map(|r| r.p_value.unwrap_or(f64::NAN))
                    .collect();
                assert_vec(&actual_p, &nums(&expected["p"])?, RTOL_VAR, "p")
            })();
            report.record(name, "anova", result);
        } else if name.starts_with("survfit_") {
            let fit = km_curves_for_case(&doc, case);
            for (aspect, value) in expected.as_object().expect("expected") {
                let result = (|| -> Result<(), String> {
                    let (fit, n) = fit.as_ref().map_err(Clone::clone)?;
                    let curves = validation_curves(fit);
                    match aspect.as_str() {
                        "summary_table_individual" => {
                            let rows =
                                survmean(&curves, n, None, 0.0, RmeanOption::Individual, 1.0)
                                    .map_err(|err| err.to_string())?;
                            check_summary_table(&rows, value)
                        }
                        "summary_table_none" => {
                            let rows = survmean(&curves, n, None, 0.0, RmeanOption::None, 1.0)
                                .map_err(|err| err.to_string())?;
                            check_summary_table(&rows, value)
                        }
                        "summary_table_scale" => {
                            let rows =
                                survmean(&curves, n, None, 0.0, RmeanOption::At(365.25), 365.25)
                                    .map_err(|err| err.to_string())?;
                            check_summary_table(&rows, value)
                        }
                        "quantile_scale" | "quantile_probs" => {
                            let probs = nums(&value["probs"])?;
                            let result = quantile_survfit(
                                &curves,
                                &probs,
                                true,
                                0.0,
                                1.0,
                                f64::EPSILON.sqrt(),
                            )
                            .map_err(|err| err.to_string())?;
                            check_quantiles(&result, value)
                        }
                        other => unsupported(format!("aspect {other}")),
                    }
                })();
                report.record(name, aspect, result);
            }
        } else {
            report.record(name, "case", unsupported(format!("case {name}")));
        }
    }
    report.finish();
}

/// One interval-censored `survfit` case (`survfit_interval` topic, or a
/// `turnbull_*` case of `validation-extra`): the fitted curves against
/// R's `survfitTurnbull` output.
fn check_turnbull_case(doc: &Value, case: &Value, report: &mut Report) {
    use crate::interval::{TurnbullInput, turnbull};
    let name = text(&case["name"]).expect("case name");
    let expected = &case["expected"];
    let aspects = ["time_surv", "counts", "std_err", "conf", "n"];
    let prepared = (|| -> Result<_, String> {
        let frame = case_frame(doc, case)?;
        let formula = text(&case["formula"]).ok_or("no formula")?;
        let lhs = formula.split('~').next().ok_or("formula")?.trim();
        let inner = lhs
            .strip_prefix("Surv(")
            .and_then(|rest| rest.strip_suffix(')'))
            .ok_or("response")?;
        let args: Vec<&str> = inner.split(',').map(str::trim).collect();
        let n = frame.nrow();
        // Surv(left, right, type = "interval2") or Surv(t1, t2, status, type = "interval")
        let (time1, time2, status) = if args.iter().any(|a| a.contains("interval2")) {
            let left = frame.get(args[0])?.numeric(args[0])?;
            let right = frame.get(args[1])?.numeric(args[1])?;
            let mut time1 = Vec::with_capacity(n);
            let mut time2 = Vec::with_capacity(n);
            let mut status = Vec::with_capacity(n);
            for i in 0..n {
                let (l, r) = (left[i], right[i]);
                let (t1, t2, s) = match (l.is_nan(), r.is_nan()) {
                    (true, false) => (r, f64::NAN, 2),
                    (false, true) => (l, f64::NAN, 0),
                    (false, false) if l == r => (l, f64::NAN, 1),
                    (false, false) => (l, r, 3),
                    (true, true) => return Err("both ends missing".to_string()),
                };
                time1.push(t1);
                time2.push(t2);
                status.push(s);
            }
            (time1, time2, status)
        } else {
            let time1 = frame.get(args[0])?.numeric(args[0])?;
            let time2 = frame.get(args[1])?.numeric(args[1])?;
            let status: Vec<i32> = frame
                .get(args[2])?
                .numeric(args[2])?
                .into_iter()
                .map(|v| v as i32)
                .collect();
            (time1, time2, status)
        };
        let terms = rhs_terms(formula);
        let group: Option<Vec<i32>> = match terms.as_slice() {
            [term] if term == "1" => None,
            [term] => Some(factor_codes(frame.get(term)?).0),
            _ => return unsupported("harness: several grouping terms"),
        };
        turnbull(&TurnbullInput {
            time1: &time1,
            time2: &time2,
            status: &status,
            weights: None,
            group: group.as_deref(),
            conf_level: 0.95,
            conf_type: "log",
            timefix: true,
        })
        .map_err(|err| err.to_string())
    })();
    match prepared {
        Err(message) => {
            for aspect in aspects {
                report.record(name, aspect, Err(message.clone()));
            }
        }
        Ok(result) => {
            // One curve: flat fields; several: a survfit object with curves.
            let expected_curves: Vec<Value> =
                if let Some(curves) = expected["fit"]["curves"].as_array() {
                    curves.clone()
                } else {
                    vec![expected.clone()]
                };
            let check = |aspect: &str| -> Result<(), String> {
                if result.curves.len() != expected_curves.len() {
                    return Err(format!(
                        "{} curves, expected {}",
                        result.curves.len(),
                        expected_curves.len()
                    ));
                }
                for (curve, exp) in result.curves.iter().zip(&expected_curves) {
                    match aspect {
                        "time_surv" => {
                            assert_vec(&curve.time, &nums(&exp["time"])?, RTOL_COEF, "time")?;
                            assert_vec(&curve.surv, &nums(&exp["surv"])?, RTOL_COEF, "surv")?;
                        }
                        "counts" => {
                            assert_vec(&curve.n_risk, &nums(&exp["n_risk"])?, RTOL_COEF, "n_risk")?;
                            assert_vec(
                                &curve.n_event,
                                &nums(&exp["n_event"])?,
                                RTOL_COEF,
                                "n_event",
                            )?;
                            assert_vec(&curve.n_censor, &nums(&exp["n_censor"])?, 0.0, "n_censor")?;
                        }
                        "std_err" => assert_vec(
                            &curve.std_err,
                            &nums(&exp["std_err"])?,
                            RTOL_VAR,
                            "std_err",
                        )?,
                        "conf" => {
                            assert_vec(&curve.lower, &nums(&exp["lower"])?, RTOL_VAR, "lower")?;
                            assert_vec(&curve.upper, &nums(&exp["upper"])?, RTOL_VAR, "upper")?;
                        }
                        "n" => {
                            let expected_n = if expected["fit"].is_null() {
                                num(&expected["n"])?
                            } else {
                                let all = nums(&expected["fit"]["n"])?;
                                all[result
                                    .curves
                                    .iter()
                                    .position(|c| std::ptr::eq(c, curve))
                                    .unwrap_or(0)]
                            };
                            assert_scalar(curve.n as f64, expected_n, 0.0, "n")?;
                        }
                        other => return unsupported(format!("aspect {other}")),
                    }
                }
                Ok(())
            };
            for aspect in aspects {
                report.record(name, aspect, check(aspect));
            }
        }
    }
}

