#[test]
fn r_fixture_files_have_metadata() {
    let dir = manifest_path("test/r/fixtures");
    let mut topics: BTreeMap<String, usize> = BTreeMap::new();
    for entry in std::fs::read_dir(&dir).expect("fixture dir") {
        let path = entry.expect("entry").path();
        if path.extension().is_some_and(|ext| ext == "json") {
            let doc: Value =
                serde_json::from_str(&std::fs::read_to_string(&path).expect("read")).expect("json");
            assert!(doc["metadata"]["survival_version"].is_string(), "{path:?}");
            let n_cases = doc["cases"].as_array().map_or(0, Vec::len);
            assert_eq!(
                n_cases,
                doc["n_cases"].as_u64().unwrap_or(0) as usize,
                "{path:?}"
            );
            topics.insert(doc["topic"].as_str().unwrap_or("").to_string(), n_cases);
        }
    }
    assert!(topics.contains_key("survfit_km"));
    assert!(topics.contains_key("coxph"));
}

#[test]
fn known_failures_are_well_formed() {
    let mut seen = std::collections::HashSet::new();
    for (id, reason) in KNOWN_FAILURES {
        assert!(!reason.is_empty(), "{id} has no reason");
        assert!(
            id.matches('/').count() >= 1,
            "{id} must be topic/case[/aspect]"
        );
        assert!(seen.insert(*id), "{id} is listed twice");
    }
}

#[test]
fn comparison_floor_is_scaled_to_the_vector() {
    // Noise around zero next to O(1) entries is within rtol * max|expected|.
    assert!(assert_vec(&[1.0, 0.0, -2.0], &[1.0, -1.2e-17, -2.0], 1e-8, "v").is_ok());
    assert!(
        assert_matrix(
            &[vec![0.0, 1.0], vec![1e-15, 0.0]],
            &[vec![0.0, 1.0], vec![0.0, 0.0]],
            1e-8,
            "m"
        )
        .is_ok()
    );
    // A difference of the same size in a vector of tiny values, or a real
    // difference, is still reported; scalars keep a pure relative tolerance.
    assert!(assert_vec(&[1e-17, 0.0], &[1e-17, 1e-17], 1e-8, "v").is_err());
    assert!(assert_vec(&[1.0, 1e-7], &[1.0, 0.0], 1e-8, "v").is_err());
    assert!(assert_scalar(1e-17, 0.0, 1e-8, "s").is_err());
    // Exact comparisons keep a zero floor.
    assert!(assert_vec(&[3.0, 1e-17], &[3.0, 0.0], 0.0, "v").is_err());
    // NaN and infinities only match themselves.
    assert!(assert_vec(&[f64::NAN, 1.0], &[f64::NAN, 1.0], 1e-8, "v").is_ok());
    assert!(assert_vec(&[0.0], &[f64::NAN], 1e-8, "v").is_err());
    assert!(assert_vec(&[f64::INFINITY], &[f64::NEG_INFINITY], 1e-8, "v").is_err());
}

#[test]
fn formula_intercept_follows_r() {
    assert!(formula_has_intercept("Surv(time, status) ~ age + sex"));
    assert!(formula_has_intercept("Surv(time, status) ~ 1"));
    assert!(!formula_has_intercept("Surv(time, status) ~ age - 1"));
    assert!(!formula_has_intercept("Surv(time, status) ~ age + sex + 0"));
    assert!(!formula_has_intercept("Surv(time, status) ~ 0 + age"));
    let frame = inline_frame(&serde_json::json!({
        "nrow": 2,
        "columns": {"time": [1.0, 2.0], "status": [1, 0], "x": [0.5, 1.5]},
        "factors": {}
    }))
    .expect("frame");
    let design = design("Surv(time, status) ~ x", &frame)
        .expect("design")
        .with_intercept();
    assert_eq!(design.names, ["(Intercept)", "x"]);
    assert_eq!(design.rows, [vec![1.0, 0.5], vec![1.0, 1.5]]);
}
